insert into public.people (id, name, wiki_title, summary, born, died, birth_place, birth_state, gender, party, education, occupation, offices, source_key) values
('abba-kabir-yusuf', 'Abba Kabir Yusuf', 'Abba_Kabir_Yusuf', 'Abba Kabir Yusuf is a Nigerian politician who has served as governor of Kano State since May 2023. He served as commissioner for Works, Housing and Transport in the Kano State Executive Council from 2011 to 2015, during the administration of Rabi''u Musa Kwankwaso. He decamped from the NNPP to APC in 2026, citing need for unity and delivering development to the people.', '1963-01-05', null, 'Gaya, Northern Region, Nigeria (now in Kano State)', 'KN', 'male', 'New Nigeria Peoples Party', 'Kaduna Polytechnic; Bayero University Kano; Federal Polytechnic, Mubi', 'Politician; engineer', '[{"title": "Governor of Kano State", "term": "Since 29 May 2023"}, {"title": "Kano State Commissioner of Works, Housing and Transport", "term": "2011–2015"}]', 'wikipedia:person:Abba_Kabir_Yusuf'),
('abdul-aziz-abubakar-yari', 'Abdul''aziz Abubakar Yari', 'Abdul''aziz_Abubakar_Yari', 'Abdul''aziz Abubakar Yari is a Nigerian politician who was elected Governor of Zamfara State in the 26 April 2011 national election, running on the All Nigeria Peoples Party (ANPP) platform. Following the merger of the ANPP and several other opposition parties into the All Progressives Congress, and his son sultan Yari became a member of the All Progressives Congress.', '1968-09-28', null, 'Talata Mafara, North-Western State, Nigeria (now in Zamfara State, Nigeria)', 'ZA', 'male', 'All Progressives Congress', 'University of Salford, Manchester, United Kingdom', 'Politician, Businessman', '[{"title": "Senator for Zamfara West", "term": "Since 13 June 2023"}, {"title": "4th Governor of Zamfara State", "term": "29 May 2011 – 29 May 2019"}]', 'wikipedia:person:Abdul''aziz_Abubakar_Yari'),
('abdul-azeez-olajide-adediran', 'Abdul-Azeez Olajide Adediran', 'Abdul-Azeez_Olajide_Adediran', 'Abdul-Azeez Olajide Adediran popularly known as Jandor, is a Nigerian politician, journalist, entrepreneur, and technocrat. He is the chairman of Datanet Project Services Ltd, The Flora Consult, Core Media Group and Halomax international Nigeria Ltd and founder, Lagosforlagos movement Lagos State. In 2023 general election, he was the Lagos state gubernatorial candidate under the People''s Democratic Party with his running mate, Funke Akindele. He received the 2021 Honorary Doctorate in Leadership and Governance by South American University.', '1977-11-25', null, null, null, 'male', null, 'The Polytechnic, Ibadan; Modul University Vienna; the Howard University School of Business', 'Energy consultant (oil and gas and renewable Energy), Fintech, Communications .; politician', '[]', 'wikipedia:person:Abdul-Azeez_Olajide_Adediran'),
('abdulrahman-abdulrazaq', 'AbdulRahman AbdulRazaq', 'AbdulRahman_AbdulRazaq', 'AbdulRahman AbdulRazaq is a Nigerian politician who has served as governor of Kwara State since 2019.', '1960-02-05', null, 'Zaria, Northern Region, Colonial Nigeria (now in Kaduna State, Nigeria)', 'KD', 'male', 'All Progressives Congress', null, 'Politician', '[{"title": "Governor of Kwara State", "term": "Since 29 May 2019"}]', 'wikipedia:person:AbdulRahman_AbdulRazaq'),
('abdulfatah-ahmed', 'Abdulfatah Ahmed', 'Abdulfatah_Ahmed', 'Abdulfatah Ahmed is a Nigerian banker and politician. He is the former Governor of Kwara State.', '1963-12-29', null, 'Share, Kwara State, Nigeria', 'KW', 'male', 'People''s Democratic Party', null, null, '[{"title": "Governor of Kwara State", "term": "29 May 2011 – 29 May 2019"}]', 'wikipedia:person:Abdulfatah_Ahmed'),
('abdulkadir-balarabe-musa', 'Abdulkadir Balarabe Musa', 'Abdulkadir_Balarabe_Musa', 'Abdulkadir Balarabe Musa CFR was a Nigerian left-wing politician who was elected Governor of Kaduna State, Nigeria during the Nigerian Second Republic, holding office from October 1979 until he was impeached on 23 June 1981. During the Nigerian Fourth Republic he was leader of the Conference of Nigerian Political Parties (CNPP), a coalition of opposition parties.', null, '2020-11-11', 'Kaya, Kaduna State, Nigeria', 'KD', 'male', 'People''s Redemption Party', null, null, '[{"title": "Governor of Kaduna State", "term": "October 1979 – 23 June 1981"}]', 'wikipedia:person:Abdulkadir_Balarabe_Musa'),
('abdulkadir-kure', 'Abdulkadir Kure', 'Abdulkadir_Kure', 'Abdulkadir Kure was a Nigerian politician who served as Governor of Niger State in Nigeria from 29 May 1999 to 29 May 2007. He was a member of the People''s Democratic Party (PDP). In May 2000, he introduced Sharia law in Niger State.', '1956-02-26', '2017-01-08', 'Lapai, Niger State, Nigeria', 'NI', 'male', 'PDP', null, null, '[{"title": "Governor of Niger State", "term": "29 May 1999 – 29 May 2007"}]', 'wikipedia:person:Abdulkadir_Kure'),
('abdullahi-adamu', 'Abdullahi Adamu', 'Abdullahi_Adamu', 'Abdullahi Adamu is a Nigerian politician who was the governor of Nasarawa State in Nigeria from 29 May 1999 to 29 May 2007. He is a member and former national chairman of the ruling Party All Progressives Congress (APC).', '1946-07-23', null, 'Keffi, Nasarawa State, Nigeria', 'NA', 'male', 'All Progressives Congress', 'University of Jos; Kaduna Polytechnic.', null, '[{"title": "National Chairman of the All Progressives Congress", "term": "22 March 2022 – 17 July 2023"}, {"title": "Governor of Nasarawa State", "term": "May 1999 – May 2007"}, {"title": "Senator of the Federal Republic of Nigeria for Nasarawa West", "term": "May 2011 – April 2022"}]', 'wikipedia:person:Abdullahi_Adamu'),
('abdullahi-sule', 'Abdullahi Sule', 'Abdullahi_Sule', 'Abdullahi Audu Sule is a Nigerian engineer, businessman, and politician who has served as the Governor of Nasarawa State since 2019. He was elected on the platform of the All Progressives Congress (APC).', '1959-12-26', null, 'Akwanga, Northern Region, British Nigeria (now in Nasarawa State, Nigeria)', 'NA', 'male', 'All Progressives Congress', 'Government Technical College, Bukuru; Plateau State Polytechnic; Indiana State University', 'Politician; engineer; businessman', '[{"title": "Governor of Nasarawa State", "term": "Since 29 May 2019"}]', 'wikipedia:person:Abdullahi_Sule'),
('abdullahi-umar-ganduje', 'Abdullahi Umar Ganduje', 'Abdullahi_Umar_Ganduje', 'Abdullahi Umar Ganduje OFR is the board chairman FAAN also is a Nigerian politician who served as the governor of Kano State from 2015 to 2023. He previously served as Rabiu Kwankwaso ''s deputy governor twice, from 1999 to 2003 and from 2011 to 2015. He is a member and former national chairman of the ruling Party All Progressives Congress (APC) from August 2023 to June 2025.', '1949-12-25', null, 'Ganduje, Northern Region, British Nigeria (now in Kano State, Nigeria)', 'KN', 'male', 'All Progressive Congress', 'Government College, Birnin Kudu', 'Politician', '[{"title": "National Chairman of the All Progressives Congress", "term": "3 August 2023 – 27 June 2025"}, {"title": "Governor of Kano State", "term": "29 May 2015 – 29 May 2023"}, {"title": "Deputy Governor of Kano State", "term": "29 May 2011 – 29 May 2015"}]', 'wikipedia:person:Abdullahi_Umar_Ganduje'),
('abiola-ajimobi', 'Abiola Ajimobi', 'Abiola_Ajimobi', 'Isiaka Abiola Adeyemi Ajimobi was a Nigerian politician who served as governor of Oyo State from 2011 to 2019, he was the first person elected to the office twice.', null, '2020-06-25', 'Oja''ba, Ibadan, Southern Region, British Nigeria (now in Oyo State, Nigeria)', 'OY', 'male', 'All Progressives Congress', 'State University of New York; Governors State University', 'Politician', '[{"title": "Governor of Oyo State", "term": "29 May 2011 – 29 May 2019"}, {"title": "Senator for Oyo South", "term": "3 June 2003 – 5 June 2007"}]', 'wikipedia:person:Abiola_Ajimobi'),
('abu-ibrahim', 'Abu Ibrahim', 'Abu_Ibrahim_(Nigerian_politician)', 'Abu Ibrahim is a Nigerian politician who was elected Senator for the Katsina South (Funtua) Senatorial district in April 2003 on the All Nigeria Peoples Party (ANPP) platform, serving for one term until May 2007. He was re-elected to the same seat in April 2011.', null, null, 'Katsina State, Nigeria', 'KT', 'male', 'All Progressives Congress', null, null, '[{"title": "Senator for Katsina South (Funtua)", "term": "May 2003 – May 2007"}, {"title": "Senator for Katsina South (Funtua)", "term": "Since May 2011"}]', 'wikipedia:person:Abu_Ibrahim_(Nigerian_politician)'),
('abubakar-atiku-bagudu', 'Abubakar Atiku Bagudu', 'Abubakar_Atiku_Bagudu', 'Abubakar Atiku Bagudu CON is a Nigerian politician who is the Nigerian minister of budget and economic planning. He served as governor of Kebbi State from 2015 to 2023. He also served as the senator representing the Kebbi Central senatorial district from 2009 to 2015.', '1961-12-26', null, null, null, 'male', 'All Progressives Congress', 'Usmanu Danfodiyo University; University of Jos', 'Politician', '[{"title": "Minister of Budget and Economic Planning", "term": "Since 21 August 2023"}, {"title": "Governor of Kebbi State", "term": "29 May 2015 – 29 May 2023"}, {"title": "Senator for Kebbi Central", "term": "2009 – 29 May 2015"}]', 'wikipedia:person:Abubakar_Atiku_Bagudu'),
('abubakar-audu', 'Abubakar Audu', 'Abubakar_Audu', 'Prince Abubakar Audu was a Nigerian career banker and politician who was the first civilian governor of Kogi State. He ruled Kogi State twice (first in the Third Republic and second, in the Fourth Republic). His first tenure was from January 1992 until November 1993 and the second from 29 May 1999 to 29 May 2003. He died due to a bleeding ulcer before the announcement of the election results on 22 November 2015, while seeking to be re-elected as governor on the platform of Nigeria''s ruling party, All Progressives Congress (APC).', null, '2015-11-22', null, null, 'male', 'All Progressives Congress', null, null, '[{"title": "Governor of Kogi State", "term": "29 May 1999 – 29 May 2003"}, {"title": "Benue State Commissioner for Finance and Economic Planning", "term": "1986–1988"}]', 'wikipedia:person:Abubakar_Audu'),
('abubakar-habu-hashidu', 'Abubakar Habu Hashidu', 'Abubakar_Habu_Hashidu', 'Alhaji Abubakar Habu Hashidu was a Nigerian politician who served as a Minister of Water Resources, minister of Agriculture and also Minister of Rural Development then further elected as governor of Gombe State from 1999 to 2003 under the platform of All People''s Party (APP).', '1944-04-10', '2018-07-27', 'Hashidu, Northern Region, British Nigeria (now in Gombe State, Nigeria)', 'GO', 'male', 'All People''s Party', 'Lincoln University', 'Politician', '[{"title": "Governor of Gombe State", "term": "29 May 1999 – 29 May 2003"}]', 'wikipedia:person:Abubakar_Habu_Hashidu'),
('abubakar-sani-bello', 'Abubakar Sani Bello', 'Abubakar_Sani_Bello', 'Abubakar Sani Bello, also known as Lolo, is a Nigerian politician who is the current senator representing the Niger North Senatorial District. He previously served as the governor of Niger State from 2015 to 2023. He is a member of All Progressives Congress.', '1967-12-17', null, 'Niger State, Nigeria', 'NI', 'male', 'All Progressives Congress', 'Economics', 'Politician', '[{"title": "Senator for Niger North", "term": "Since 13 June 2023"}, {"title": "Governor of Niger State", "term": "29 May 2015 – 29 May 2023"}]', 'wikipedia:person:Abubakar_Sani_Bello'),
('achike-udenwa', 'Achike Udenwa', 'Achike_Udenwa', 'Achike Udenwa is a Nigerian politician who was governor of Imo State from 29 May 1999 to 29 May 2007. He is a member of the People''s Democratic Party. He was succeeded by Chief Ikedi Ohakim on 29 May 2007.', null, null, null, null, 'male', 'People''s Democratic Party', null, null, '[{"title": "3rd Governor of Imo State", "term": "29 May 1999 – 29 May 2007"}, {"title": "Minister of Commerce and Industry", "term": "17 December 2008 – 17 March 2010"}]', 'wikipedia:person:Achike_Udenwa'),
('adams-oshiomhole', 'Adams Oshiomhole', 'Adams_Oshiomhole', 'Adams Aliyu Oshiomhole CON is a Nigerian politician who has served as the senator representing the Edo North senatorial district since 2023. He is a former national chairman of the All Progressive Congress. He previously served as the president of the Nigeria Labour Congress from 1999 to 2007 and as governor of Edo State from 2008 to 2016.', '1952-04-04', null, 'Iyamho, Auchi, Southern Region, British Nigeria (now in Edo State, Nigeria)', 'ED', 'male', 'All Progressives Congress', null, 'Politician', '[{"title": "Senator for Edo North", "term": "Since 13 June 2023"}, {"title": "National Chairman of the All Progressives Congress", "term": "20 July 2018 – 16 June 2020"}, {"title": "Governor of Edo State", "term": "12 November 2008 – 12 November 2016"}, {"title": "President of the Nigeria Labour Congress", "term": "1999–2007"}]', 'wikipedia:person:Adams_Oshiomhole'),
('adamu-aliero', 'Adamu Aliero', 'Adamu_Aliero', 'Muhammad Adamu Aliero is a Nigerian politician who is the senator representing Kebbi Central senatorial district since 2015. He previously served in that position from 2007 to 2008. He served as the governor of Kebbi State from 1999 to 2007. He is a member of the All progressives Congress.', '1957-01-01', null, 'Aliero, Northern Region, British Nigeria (now in Kebbi State, Nigeria)', 'KE', 'male', 'Peoples Democratic Party', 'Ahmadu Bello University', 'Politician', '[{"title": "Senator for Kebbi Central", "term": "Since 9 June 2015"}, {"title": "Minister of the Federal Capital Territory", "term": "17 December 2008 – 17 March 2010"}, {"title": "Governor of Kebbi State", "term": "29 May 1999 – 29 May 2007"}]', 'wikipedia:person:Adamu_Aliero'),
('adamu-waziri', 'Adamu Waziri', 'Adamu_Waziri', 'Adamu Maina Waziri was appointed Nigerian minister of Police Affairs on 6 April 2010, when Acting President Goodluck Jonathan announced his new cabinet.', '1952-09-14', null, null, null, 'male', 'PDP', null, null, '[{"title": "Federal Minister of State for Agriculture", "term": "July 2007 – 29 October 2008"}, {"title": "Minister of Police Affairs", "term": "6 April 2010 – 2015"}]', 'wikipedia:person:Adamu_Waziri'),
('adebayo-adefarati', 'Adebayo Adefarati', 'Adebayo_Adefarati', 'Adebayo Adefarati was a Nigerian politician who served as governor of Ondo State from 1999 to 2003.', null, '2007-03-29', 'Akungba Akoko, Southern Region, British Nigeria (now in Ondo State, Nigeria)', 'ON', 'male', null, null, 'Politician', '[{"title": "Governor of Ondo State", "term": "29 May 1999 – 29 May 2003"}, {"title": "Ondo State Commissioner for Works and Transport", "term": "1979–1983"}]', 'wikipedia:person:Adebayo_Adefarati'),
('adebayo-adelabu', 'Adebayo Adelabu', 'Adebayo_Adelabu', 'Adebayo Adelabu OFR is a former deputy governor, operations of the Central Bank of Nigeria who served as the Federal Minister of Power of Nigeria. He resigned on April 22, 2026. He was also an Oyo State gubernatorial candidate for the All Progressives Congress in 2019.', '1970-09-28', null, 'Ibadan, Oyo State, Nigeria', 'OY', 'male', 'APC', 'Lagelu Grammar School, Ibadan; Obafemi Awolowo University; Harvard Business School, Boston, USA', null, '[{"title": "Federal Minister of Power", "term": "August 21, 2023 – April 22, 2026"}, {"title": "Deputy Governor Operations, Central Bank of Nigeria", "term": "April 9, 2014 – May 24, 2018"}]', 'wikipedia:person:Adebayo_Adelabu'),
('adebayo-alao-akala', 'Adebayo Alao-Akala', 'Adebayo_Alao-Akala', 'Christopher Adebayo Alao-Akala was a Nigerian politician and police officer who served as the governor of Oyo State in 2006, and again from 2007 to 2011. He was the candidate of the Action Democratic Party in the 2019 Oyo State gubernatorial election.', '1950-06-03', '2022-01-12', 'Ogbomoso, Southern Region, British Nigeria (now in Oyo State, Nigeria)', 'OY', 'male', 'Peoples Democratic Party', 'Lead City University; University of Ibadan', 'Politician; police officer', '[{"title": "Governor of Oyo State", "term": "29 May 2007 – 29 May 2011"}, {"title": "Deputy Governor of Oyo State", "term": "7 December 2006 – 29 May 2007"}]', 'wikipedia:person:Adebayo_Alao-Akala'),
('adebisi-akande', 'Adebisi Akande', 'Adebisi_Akande', 'Chief Abdulkareem Adebisi Bamdele Akande, CFR, is a Nigerian politician who served as the governor of Osun State from 1999 to 2003, as a member of the Alliance for Democracy (AD) party. Following his governorship, he served for eleven consecutive years (2003–2014) as the National Chairman of the Alliance for Democracy, the Action Congress (AC), and the Action Congress of Nigeria (ACN). He subsequently became the founding Interim National Chairman of the ruling party, the All Progressives Congress (APC).', '1939-01-16', null, 'Ila Orangun, Southern Region, British Nigeria (now in Osun State, Nigeria)', 'OS', 'male', 'All Progressives Congress', null, 'Politician', '[{"title": "Governor of Osun State", "term": "29 May 1999 – 29 May 2003"}, {"title": "Deputy Governor of Oyo State", "term": "1982 – 1 October 1983"}]', 'wikipedia:person:Adebisi_Akande'),
('adekunle-akinlade', 'Adekunle Akinlade', 'Adekunle_Akinlade', 'Adekunle Abdulkabir Akinlade Triple A is a Nigerian politician. He represented Egbado South and Ipokia federal constituency in the House of Representatives. He left the All Progressive Congress and joined the Allied Peoples Movement to run for Governor of Ogun State in the 2019 election.', '1969-10-09', null, 'Ipokia, Ogun State, Nigeria', 'OG', 'male', null, null, 'Politician', '[]', 'wikipedia:person:Adekunle_Akinlade'),
('ademola-adeleke', 'Ademola Adeleke', 'Ademola_Adeleke', 'Ademola Nurudeen Jackson Adeleke is a Nigerian politician and businessman who has been serving as the governor of Osun State since 2022. He served as the senator representing the Osun-West senatorial district from 2017 to 2019.', '1960-05-13', null, 'Enugu State, Nigeria', 'EN', 'male', 'Accord', 'Jacksonville State University; Atlanta Metropolitan State College', 'Politician; businessman; administrator', '[{"title": "Governor of Osun State", "term": "Since 27 November 2022"}, {"title": "Senator for Osun West", "term": "2017–2019"}]', 'wikipedia:person:Ademola_Adeleke'),
('adewolu-ladoja', 'Adewolu Ladoja', 'Adewolu_Ladoja', 'Oba Adewolu Ladoja is a Nigerian monarch. He is the 44th Olubadan of Ibadan.', '1944-09-25', null, 'Gambari, Ibadan, Southern Region, British Nigeria (now in Oyo State, Nigeria)', 'OY', 'male', 'Zenith Labour Party', 'Olivet Baptist High School; University of Liège', 'Politician; Businessman', '[{"title": "Governor of Oyo State", "term": "7 December 2006 – 29 May 2007"}, {"title": "Senator for Oyo South", "term": "5 December 1992 – 17 November 1993"}]', 'wikipedia:person:Adewolu_Ladoja'),
('agboola-ajayi', 'Agboola Ajayi', 'Agboola_Ajayi', 'Alfred Agboola Ajayi is a Nigerian politician, lawyer, and businessman who served as deputy governor of Ondo State from 2017 to 2021.', '1968-09-24', null, 'Kiribo, Ese-Odo, Western State, Nigeria (now in Ondo State)', 'ON', 'male', 'Peoples Democratic Party', 'Igbinedion University, Okada', 'Politician; lawyer; businessman', '[{"title": "Deputy Governor of Ondo State", "term": "24 February 2017 – 24 February 2021"}, {"title": "Member of the House of Representatives of Nigeria from Ondo", "term": "5 June 2007 – 6 June 2011"}]', 'wikipedia:person:Agboola_Ajayi'),
('agbu-kefas', 'Agbu Kefas', 'Agbu_Kefas', 'Agbu Kefas is a Nigerian politician and retired Nigerian army lieutenant colonel who has served as the governor of Taraba State since 2023.', '1970-11-12', null, 'Wukari, North-Eastern State (now in Taraba State), Nigeria', 'TA', 'male', 'Peoples Democratic Party', 'Nigerian Defence Academy; University of Ibadan; Delta State University, Abraka', 'Politician; military officer', '[{"title": "Governor of Taraba State", "term": "Since 29 May 2023"}]', 'wikipedia:person:Agbu_Kefas'),
('ahmad-aliyu', 'Ahmad Aliyu', 'Ahmad_Aliyu', 'Ahmad Aliyu Sokoto is a Nigerian politician who is the Governor of Sokoto State. He was a former commissioner and was the deputy governor of Sokoto State from 2015 until his resignation in 2018.', '1970-01-01', null, 'Sokoto, North-Western State, Nigeria (now in Sokoto State)', 'SO', 'male', 'All Progressives Congress', null, 'Politician', '[{"title": "Governor of Sokoto State", "term": "Since 29 May 2023"}, {"title": "Deputy Governor of Sokoto State", "term": "29 May 2015 – 14 November 2018"}]', 'wikipedia:person:Ahmad_Aliyu'),
('ahmad-sani-yerima', 'Ahmad Sani Yerima', 'Ahmad_Sani_Yerima', 'Ahmed Rufai Sani Yerima is a Nigerian politician who was Governor of Zamfara State from May 1999 to May 2007, and served as Senator for Zamfara West and Deputy Minority Leader in the Senate. He is a member of the All Progressives Congress (APC).', '1960-07-22', null, 'Anka, Northern Region, British Nigeria (now in Zamfara State, Nigeria)', 'ZA', 'male', 'All Progressives Congress', null, null, '[{"title": "Governor of Zamfara State", "term": "29 May 1999 – 29 May 2007"}, {"title": "Senator of the Federal Republic of Nigeria", "term": "June 2007 – June 2019"}]', 'wikipedia:person:Ahmad_Sani_Yerima'),
('ahmadu-fintiri', 'Ahmadu Fintiri', 'Ahmadu_Fintiri', 'Ahmadu Umaru Fintiri is a Nigerian politician who has served as the governor of Adamawa State since 2019. He was a member of the Adamawa State House of Assembly and served as Speaker of the Assembly. He became the acting governor of Adamawa State following the impeachment of Governor Murtala Nyako in July 2014, serving until 8 October 2014.', '1967-10-27', null, 'Madagali, North-Eastern State (now in Adamawa State), Nigeria', 'AD', 'male', 'All Progressives Congress', 'University of Maiduguri', 'Politician', '[{"title": "Governor of Adamawa State", "term": "Since 29 May 2019"}, {"title": "Speaker of the Adamawa State House of Assembly", "term": "10 October 2014 – 5 June 2015"}, {"title": "Deputy Speaker of the Adamawa State House of Assembly", "term": "?–2011"}, {"title": "Member of Adamawa State House of Assembly", "term": "? – 5 June 2015"}]', 'wikipedia:person:Ahmadu_Fintiri'),
('ahmed-makarfi', 'Ahmed Makarfi', 'Ahmed_Makarfi', 'Ahmed Mohammed Makarfi is a Nigerian politician who is a former chairman of the Peoples Democratic Party. He was governor of Kaduna State from 29 May 1999 to 29 May 2007, and was elected Senator for Kaduna North senatorial district in April 2007. He is a member of the Peoples Democratic Party (PDP).', '1956-08-08', null, 'Makarfi, Northern Region, British Nigeria (now in Kaduna State, Nigeria)', 'KD', 'male', 'Peoples Democratic Party', null, 'Politician', '[{"title": "Senator for Kaduna North", "term": "14 November 2011 – 6 June 2015"}, {"title": "Governor of Kaduna State", "term": "29 May 1999 – 29 May 2007"}]', 'wikipedia:person:Ahmed_Makarfi'),
('ahmed-usman-ododo', 'Ahmed Usman Ododo', 'Ahmed_Usman_Ododo', 'Ahmed Usman Ododo is a Nigerian accountant and politician who has served as governor of Kogi State since 2024. He is a member of the All Progressives Congress (APC).', '1978-01-01', null, 'Okene, Kogi State, Nigeria', 'KO', 'male', 'All Progressives Congress', 'Ahmadu Bello University; University of Lagos', 'Politician; accountant', '[{"title": "Governor of Kogi State", "term": "Since 27 January 2024"}]', 'wikipedia:person:Ahmed_Usman_Ododo'),
('aisha-alhassan', 'Aisha Alhassan', 'Aisha_Alhassan', 'Aisha Jummai Al-Hassan, popularly known as Mama Taraba, was a Nigerian lawyer and politician who served as the Federal Minister of Women Affairs from her appointment in 2015 until her resignation in 2018. She previously served as the senator representing the Taraba North senatorial district from 2011 to 2015.', '1959-09-16', '2021-05-07', 'Jalingo, Northern Region, British Nigeria (now in Taraba State, Nigeria)', 'TA', 'female', 'Peoples Democratic Party', null, 'Politician; lawyer', '[{"title": "Federal Minister of Women Affairs", "term": "11 November 2015 – 29 September 2018"}, {"title": "Senator for Taraba North", "term": "6 June 2011 – 6 June 2015"}]', 'wikipedia:person:Aisha_Alhassan'),
('aishatu-dahiru-ahmed', 'Aishatu Dahiru Ahmed', 'Aishatu_Dahiru_Ahmed', 'Aishatu Dahiru Ahmed, popularly known as Aisha Binani, is a Nigerian politician and entrepreneur who was the senator for Adamawa Central from 2019 to 2023. On 30 March 2020, she was appointed Gimbiyar Adamawa by the Adamawa Emirate Council.', '1971-08-11', null, 'Kaduna, North-Central State (now Kaduna State), Nigeria', 'KD', 'female', 'All Progressives Congress', 'Federal Polytechnic, Mubi; University of Southampton; Nasarawa State University', 'Politician; engineer; entrepreneur', '[{"title": "Senator for Adamawa Central", "term": "11 June 2019 – 11 June 2023"}, {"title": "Member of the House of Representatives of Nigeria from Adamawa", "term": "6 June 2011 – 6 June 2015"}]', 'wikipedia:person:Aishatu_Dahiru_Ahmed'),
('akachukwu-sullivan-nwankpo', 'Akachukwu Sullivan Nwankpo', 'Akachukwu_Sullivan_Nwankpo', 'Akachukwu Sullivan Nwankpo is a Nigerian politician, Igbo political leader and peace-maker. He served as the Special Advisor on Technical Matters to President Goodluck Jonathan and Secretary/Member of the Presidential Subsidy Reinvestment and Empowerment Program (SURE-P) Committee until 1 August 2013. He is a member of the African Democratic Congress', '1962-04-10', null, 'Ozubulu in Ekwusigo Local Government, Anambra State, Nigeria', 'AN', 'male', 'African Democratic Congress', null, null, '[]', 'wikipedia:person:Akachukwu_Sullivan_Nwankpo'),
('akinwunmi-ambode', 'Akinwunmi Ambode', 'Akinwunmi_Ambode', 'Akinwunmi Ambode is a Nigerian politician who served as governor of Lagos State from 2015 to 2019. He was a civil servant for 27 years and a financial consultant before running for public office.', '1963-06-14', null, 'Epe, Lagos State, Nigeria', 'LA', 'male', 'All Progressives Congress', 'Federal Government College, Warri; University of Lagos; Wharton Business School', 'Politician; accountant', '[{"title": "14th Governor of Lagos State", "term": "29 May 2015 – 29 May 2019"}]', 'wikipedia:person:Akinwunmi_Ambode'),
('alex-otti', 'Alex Otti', 'Alex_Otti', 'Alexander Chioma Otti, Sr. OFR is a Nigerian economist, banker, investor, philanthropist, and politician, serving as the current Governor of Abia State in Nigeria. He is from Umuru Umuehim in Isialangwa South LGA. Otti is the former Group Managing Director of Diamond Bank Plc, a retail financial institution in Nigeria. Otti was a gubernatorial candidate of Abia State on the platform of All Progressives Grand Alliance (APGA). On 31 December 2015, The Court of Appeal which sat in Owerri removed Okezie Ikpeazu of the Peoples Democratic Party as governor of Abia State and declared Otti the winner of the April 11 and April 25 Governorship elections in the state.', '1965-02-18', null, 'Abia State, Nigeria', 'AB', 'male', 'Labour Party', 'University of Lagos', 'Politician, Banker, Economist.; Former MD and CEO, Diamond Bank, Present Governor of Abia state.', '[{"title": "Governor of Abia State", "term": "Since 29 May 2023"}]', 'wikipedia:person:Alex_Otti'),
('ali-modu-sheriff', 'Ali Modu Sheriff', 'Ali_Modu_Sheriff', 'Ali Modu Sheriff is a Nigerian politician who served as governor of Borno State from 2003 to 2011. He was the first governor to serve two consecutive terms.', null, null, 'Ngala, Northern Region, British Nigeria (now in Borno State, Nigeria)', 'BO', 'male', 'All Progressive Congress', null, null, '[{"title": "Chairman of the PDP National Working Committee Acting", "term": "16 February 2016 – 21 May 2016"}, {"title": "Governor of Borno State", "term": "29 May 2003 – 29 May 2011"}, {"title": "Senator for Borno Central", "term": "3 June 1999 – 3 June 2003"}]', 'wikipedia:person:Ali_Modu_Sheriff'),
('aliyu-doma', 'Aliyu Doma', 'Aliyu_Doma', 'Aliyu Akwe Doma was a Nigerian civil servant who became governor of Nasarawa State in May 2007, standing for the People''s Democratic Party (PDP).', '1942-09-01', '2018-03-06', 'Doma, Nasarawa State Nigeria', 'NA', 'male', 'People''s Democratic Party', null, null, '[{"title": "Governor of Nasarawa State", "term": "29 May 2007 – May 2011"}]', 'wikipedia:person:Aliyu_Doma'),
('aliyu-magatakarda-wamakko', 'Aliyu Magatakarda Wamakko', 'Aliyu_Magatakarda_Wamakko', 'Aliyu Magatakarda Wamakko is a Nigerian politician who served as governor of Sokoto State, between 2007 and 2015.', '1953-03-01', null, 'Wamakko, Sokoto State, Nigeria', 'SO', 'male', 'APC', null, null, '[{"title": "Governor of Sokoto State", "term": "29 May 2007 – 29 May 2015"}]', 'wikipedia:person:Aliyu_Magatakarda_Wamakko'),
('aminu-bello-masari', 'Aminu Bello Masari', 'Aminu_Bello_Masari', 'Aminu Bello Masari is a Nigerian politician who served as the Governor of Katsina State from 2015 to 2023. He previously served as the Commissioner for Works, Housing, and Transport in Katsina State from 1991 to 1993, and was the Speaker of the House of Representatives between 2003 and 2007.', '1950-05-29', null, 'Kafur, Northern Region, British Nigeria (now Katsina State, Nigeria)', 'KT', 'male', 'All Progressives Congress', null, 'Politician', '[{"title": "Governor of Katsina State", "term": "29 May 2015 – 29 May 2023"}, {"title": "9th Speaker of the House of Representatives of Nigeria", "term": "3 June 2003 – 6 June 2007"}]', 'wikipedia:person:Aminu_Bello_Masari'),
('aminu-tambuwal', 'Aminu Tambuwal', 'Aminu_Tambuwal', 'Aminu Tambuwal is a Nigerian lawyer and politician. A member of the Peoples Democratic Party, he represented the Tambuwal / Kebbe Federal Constituency of Sokoto State in the House of Representatives from 2003 to 2015, including serving as the twelfth Speaker of the House of Representatives of Nigeria from 2011 to 2015.', '1966-01-10', null, 'Tambuwal, Northern Region, Nigeria (now in Sokoto State)', 'SO', 'male', 'African Democratic Congress', 'Usman Danfodio University (LL.B.)', 'Politician; lawyer', '[{"title": "Senator for Sokoto South", "term": "Since 13 June 2023"}, {"title": "Governor of Sokoto State", "term": "29 May 2015 – 29 May 2023"}, {"title": "12th Speaker of the House of Representatives of Nigeria", "term": "6 June 2011 – 29 May 2015"}, {"title": "House Deputy Chief Whip", "term": "5 June 2007 – 6 June 2011"}, {"title": "Member of the House of Representatives of Nigeria from Sokoto", "term": "3 June 2003 – 29 May 2015"}]', 'wikipedia:person:Aminu_Tambuwal'),
('andy-uba', 'Andy Uba', 'Andy_Uba', 'Emmanuel Nnamdi Uba is a Nigerian politician who served as Senator for the Anambra South Senatorial District of Anambra State from 2011 to 2019. Uba also won the 2007 Anambra State gubernatorial election on the platform of the People''s Democratic Party but was declared unduly elected by the Supreme Court of Nigeria a month later. He defected to the ruling All Progressives Congress in February 2017; the leadership crises engulfing the former ruling party PDP may have motivated his decision.', '1958-12-14', null, 'Enugu, Eastern Region, British Nigeria (now Enugu, Enugu State, Nigeria)', 'EN', 'male', 'All Progressives Congress', null, null, '[{"title": "Senator of the Federal Republic of Nigeria", "term": "May 2011 – May 2019"}]', 'wikipedia:person:Andy_Uba'),
('asue-ighodalo', 'Asue Ighodalo', 'Asue_Ighodalo', 'Asuerinme Ighodalo is a Nigerian lawyer and politician. He is from Okaigben, Ewohimi, Esan South East LGA, Edo State, Nigeria. He was a candidate in the 2024 Edo State gubernatorial election. He is a founding partner of the law firm Banwo & Ighodalo, alongside Femi Olubanwo, a corporate and commercial law practice in Nigeria, specializing in advising major corporations on corporate finance, capital markets, energy and natural resources, mergers and acquisitions, banking and securitization and project finance. He was the chairman of Sterling Bank, a director at the Nigerian Sovereign Investment Authority (NSIA), and chairman of the Nigerian Economic Summit Group (NESG).', null, null, null, null, 'male', null, 'King''s College, Lagos, University of Ibadan; Nigerian Law School; London School of Economics', 'Chairman, Sterling Bank Plc, Director, Nigerian Sovereign Investment Authority, Chairman Nigerian Economic Summit Group.', '[]', 'wikipedia:person:Asue_Ighodalo'),
('atiku-abubakar', 'Atiku Abubakar', 'Atiku_Abubakar', 'Atiku Abubakar GCON is a Nigerian politician and businessman who served as the vice president of Nigeria from 1999 to 2007 during the presidency of Olusegun Obasanjo. He ran for the office of governor of Adamawa State in 1990 and 1996 unsuccessfully, but won in 1998. Before he was sworn in, he was selected as running mate to former military leader, Olusegun Obasanjo, during the 1999 presidential election and was re-elected in 2003.', '1946-11-25', null, 'Jada, British Cameroon (now Jada, Adamawa State, Nigeria)', 'AD', 'male', 'African Democratic Congress', 'Master of Arts degree in International Relations', 'Politician; businessman', '[{"title": "11th Vice President of Nigeria", "term": "29 May 1999 – 29 May 2007"}]', 'wikipedia:person:Atiku_Abubakar'),
('attahiru-bafarawa', 'Attahiru Bafarawa', 'Attahiru_Bafarawa', 'Alhaji Attahiru Dalhatu Bafarawa is a Nigerian politician who served as the executive governor of Sokoto State from 29 May 1999 to 29 May 2007.', '1954-11-04', null, null, null, 'male', null, null, null, '[{"title": "Governor of Sokoto State", "term": "29 May 1999 – 29 May 2007"}]', 'wikipedia:person:Attahiru_Bafarawa'),
('ayo-fayose', 'Ayo Fayose', 'Ayo_Fayose', 'Peter Ayodele Fayose is a Nigerian politician who served as governor of Ekiti State from 2003 to 2006, and again from 2014 to 2018.', '1960-11-15', null, 'Afao Ekiti, Western Region (now in Ekiti State), Nigeria', 'EK', 'male', 'Peoples Democratic Party', null, 'Politician', '[{"title": "Governor of Ekiti State", "term": "16 October 2014 – 16 October 2018"}]', 'wikipedia:person:Ayo_Fayose'),
('ayogu-eze', 'Ayogu Eze', 'Ayogu_Eze', 'Ayogu Eze was a Nigerian politician from Enugu Ezike, elected Senator for the Enugu North Senatorial District of Enugu State, taking office on 5 June 2007. He was later a member of the All Progressives Congress, APC but was elected to the senate under the People''s Democratic Party (PDP).', '1958-11-23', '2024-04-25', 'Enugu State, Federation of Nigeria', 'EN', 'male', 'APC', null, null, '[{"title": "Senator from Enugu North Senatorial District", "term": "5 June 2007 – 6 June 2015"}]', 'wikipedia:person:Ayogu_Eze'),
('babagana-zulum', 'Babagana Zulum', 'Babagana_Zulum', 'Babagana Umara Zulum CON mni is a Nigerian Professor and Politician who is the current governor of Borno State since 2019 under the platform of the All Progressives Congress (APC).', '1969-08-25', null, 'Mafa, North-Eastern State, Nigeria (now in Borno State)', 'BO', 'male', 'All Progressives Congress', 'University of Maiduguri', 'Politician; professor', '[{"title": "Governor of Borno State", "term": "Since 29 May 2019 Kadafur Acting: 29 April 2021 to 19 May 2021"}, {"title": "Borno State Commissioner for Reconstruction, Rehabilitation and Resettlement", "term": "17 September 2015 – 29 May 2019"}]', 'wikipedia:person:Babagana_Zulum'),
('babajide-sanwo-olu', 'Babajide Sanwo-Olu', 'Babajide_Sanwo-Olu', 'Babajide Olusola Sanwo-Olu CON is a Nigerian politician who has served as the governor of Lagos State since 2019.', '1965-06-25', null, 'Lagos, Nigeria', 'LA', 'male', 'All Progressives Congress', 'University of Lagos; London Business School; Lagos Business School', 'Politician; banker', '[{"title": "15th Governor of Lagos State", "term": "Since 29 May 2019"}]', 'wikipedia:person:Babajide_Sanwo-Olu'),
('babatunde-fashola', 'Babatunde Fashola', 'Babatunde_Fashola', 'Babatunde Raji Fashola CON SAN is a Nigerian lawyer and politician who served as the federal minister of Works and Housing of Nigeria from 2019 to 2023. He was minister of Power, Works and Housing from 2015 to 2019, and served two terms as governor of Lagos State from 2007 to 2015.', '1963-06-28', null, 'Lagos, Nigeria', 'LA', 'male', 'All Progressives Congress', null, 'Politician; lawyer', '[{"title": "Minister of Works and Housing", "term": "21 August 2019 – 29 May 2023"}, {"title": "Minister of Power, Works and Housing", "term": "11 November 2015 – 28 May 2019"}, {"title": "13th Governor of Lagos State", "term": "29 May 2007 – 29 May 2015"}]', 'wikipedia:person:Babatunde_Fashola'),
('bala-mande', 'Bala Mande', 'Bala_Mande', 'Colonel Bala Mohammed Mande is a former Military Administrator of Nasarawa State. He was later appointed Minister of Environment in the Cabinet of President Olusegun Obasanjo.', null, null, null, null, 'male', null, null, null, '[{"title": "Federal Minister of Environment", "term": "July 2003 – June 2005"}, {"title": "Military Administrator of Nasarawa State", "term": "6 August 1998 – 29 May 1999"}]', 'wikipedia:person:Bala_Mande'),
('bala-mohammed', 'Bala Mohammed', 'Bala_Mohammed', 'Bala Abdulkadir Mohammed CON is a Nigerian politician who has served as governor of Bauchi State since 2019. A member of the Allied Peoples Movement, he was the former minister of the Federal Capital Territory (FCT) from 2010 to 2015, and senator representing Bauchi South senatorial district from 2007 to 2010.', '1958-10-05', null, 'Alkaleri, Northern Region, British Nigeria', null, 'male', 'Allied Peoples Movement', 'University of Maiduguri', 'Politician', '[{"title": "Governor of Bauchi State", "term": "Since 29 May 2019"}, {"title": "Minister of Federal Capital Territory", "term": "8 April 2010 – 28 May 2015"}, {"title": "Senator for Bauchi South", "term": "5 June 2007 – 8 April 2010"}]', 'wikipedia:person:Bala_Mohammed'),
('bassey-albert-akpan', 'Bassey Albert Akpan', 'Bassey_Albert_Akpan', 'Bassey Albert Akpan CON is a Nigerian politician who served as a member of the Senate of Nigeria from June 2015 to January 2023. He previously served as the Commissioner of Finance in Akwa Ibom State from 2007 to 2014. He was first elected to the Senate in March 2015, to represent the Akwa Ibom North-East Senatorial District and he won re-election in the February 2019 senatorial elections. He is a member of the Young Progressives Party (YPP).', '1972-10-28', null, 'Ibiono Ibom LGA, Akwa Ibom State, Nigeria', 'AK', 'male', 'All Progressives Congress Nigeria', null, null, '[{"title": "Senator of the Federal Republic of Nigeria from Akwa Ibom North-East Senatorial District", "term": "9 June 2015 – Jan 2023"}, {"title": "Commissioner for Finance Akwa Ibom State, Nigeria", "term": "7 August 2007 – 24 April 2014"}]', 'wikipedia:person:Bassey_Albert_Akpan'),
('bassey-otu', 'Bassey Otu', 'Bassey_Otu', 'Bassey Edet Otu popularly known as Sweet Prince is a Nigerian politician and the current governor of Cross River State Southern Nigeria. who served as a onetime senator for Cross River South from 2011 to 2015, and a onetime representative of Calabar Municipal/Odukpani constituency of Cross River State, in the House of Representatives from 2003 to 2011.', '1959-10-18', null, 'Calabar, Eastern Region, British Nigeria (now in Cross River State, Nigeria)', 'CR', 'male', 'All Progressives Congress', null, 'Politician', '[{"title": "Governor of Cross River State", "term": "Since 29 May 2023"}, {"title": "Senator for Cross River South", "term": "6 June 2011 – 6 June 2015"}, {"title": "Member of the House of Representatives of Nigeria from Cross River", "term": "3 June 2003 – 6 June 2011"}]', 'wikipedia:person:Bassey_Otu'),
('bello-matawalle', 'Bello Matawalle', 'Bello_Matawalle', 'Bello Muhammad popularly known as Bello Matawalle is a Nigerian politician and teacher who has served as the minister of state for defence since 2023. He previously served as the governor of Zamfara State from 2019 to 2023.', '1969-02-12', null, 'Maradun, North-Western State (now in Zamfara State), Nigeria', 'ZA', 'male', 'All Progressives Congress', 'Yaba College of Technology; University of West London', 'Politician; teacher', '[{"title": "Minister of State for Defence", "term": "Since 21 August 2023"}, {"title": "5th Governor of Zamfara State", "term": "29 May 2019 – 29 May 2023"}]', 'wikipedia:person:Bello_Matawalle'),
('ben-ayade', 'Ben Ayade', 'Ben_Ayade', 'Benedict Bengiuoshuye Ayade CON is a Nigerian politician who served as the governor of Cross River State from 2015 to 2023. He served as Senator for Cross River North from 2011 to 2015.', '1968-03-02', null, 'Kakum, Cross River State, Nigeria', 'CR', 'male', 'All Progressives Congress', 'St. Stephens Primary School', 'Politician; lawyer; environmentalist', '[{"title": "Governor of Cross River State", "term": "29 May 2015 – 29 May 2023"}, {"title": "Senator for Cross River North", "term": "6 June 2011 – 29 May 2015"}]', 'wikipedia:person:Ben_Ayade'),
('benard-odoh', 'Benard Odoh', 'Benard_Odoh', 'Benard Ifeanyi Odoh is a Nigerian politician and professor of applied geophysics who served as the vice-chancellor of Nnamdi Azikiwe University, Awka, Anambra State, for 22 days (29 October - 20 November 2024). He was the Secretary to the Ebonyi State Government from 2015 to 2018. He also was the gubernatorial nominee of the All Progressives Grand Alliance in Ebonyi State in 2023.', '1975-08-05', null, 'Ondo town, Ondo State', 'ON', 'male', null, null, 'Politician, Academic', '[{"title": "Vice Chancellor of Nnamdi Azikiwe University", "term": "October 29, 2024 – November 20, 2024"}, {"title": "Secretary to Ebonyi State Government", "term": "2015–2018"}]', 'wikipedia:person:Benard_Odoh'),
('bindow-jibrilla', 'Bindow Jibrilla', 'Bindow_Jibrilla', 'Mohammed Umaru Jibrilla, known as Bindow Jibrilla, is a Nigerian businessman and politician who served as governor of Adamawa State from 2015 to 2019. He previously served as the senator representing Adamawa North senatorial district from 2011 to 2015.', '1965-04-15', null, 'Adamawa State, Nigeria', 'AD', 'male', 'All Progressive Congress', null, 'Politician; businessman', '[{"title": "Governor of Adamawa State", "term": "29 May 2015 – 29 May 2019"}, {"title": "Senator for Adamawa North", "term": "6 June 2011 – 29 May 2015"}]', 'wikipedia:person:Bindow_Jibrilla'),
('biodun-oyebanji', 'Biodun Oyebanji', 'Biodun_Oyebanji', 'Abiodun Abayomi Oyebanji is a Nigerian politician who has served as the governor of Ekiti State since 2022. He was a former Secretary to the Ekiti State Government and a former Chief of Staff to the Governor of Ekiti State. He was elected governor during the 2022 Ekiti State gubernatorial election, having defeated Olusegun Oni of the Social Democratic Party and Bisi Kolawole of the Peoples Democratic Party.', '1967-12-21', null, 'Ikogosi, Western State (now in Ekiti State), Nigeria', 'EK', 'male', 'All Progressives Congress', 'Masters in International Relations & Strategic Studies', null, '[{"title": "Governor of Ekiti State", "term": "Since 16 October 2022"}, {"title": "Secretary to the Ekiti State Government", "term": "18 October 2018 – 7 December 2021"}]', 'wikipedia:person:Biodun_Oyebanji'),
('blessing-nwagba', 'Blessing Nwagba', 'Blessing_Nwagba', 'Blessing Okwuchi Nwagba is a Nigerian politician. She is currently serving as a member of the Abia State House of Assembly as the committee chairman on women affairs, social welfare and health representing Aba North Constituency. She is a sociologist by profession and former director of Belzy Pharmaceuticals, Belzy Farms, Belzy Fashion and Fulfillment International Academy and College.', null, null, 'Abia State, Nigeria', 'AB', 'female', null, 'B.Sc., M.Sc., Ph.D. in Sociology', 'Politician, sociologist', '[{"title": "Member of the Abia State House of Assembly", "term": "2011–2020"}]', 'wikipedia:person:Blessing_Nwagba'),
('bola-oyebamiji', 'Bola Oyebamiji', 'Bola_Oyebamiji', 'Bola Oyebamiji is a Nigerian politician and banker, serving as the Managing Director/CEO of the National Inland Waterways Authority. Previously, he was the Commissioner for Finance in Osun State during the administrations of former Governors Rauf Aregbesola and Gboyega Oyetola. Before his tenure as Commissioner, Oyebamiji was the Managing Director/CEO of Omoluabi Holdings Limited (formerly OSICOL). In 2023, he served as Special Adviser to Gboyega Oyetola, the pioneer Minister of Marine and Blue Economy, before his appointment as CEO of the National Inland Waterways Authority.', null, null, null, null, 'male', null, null, null, '[]', 'wikipedia:person:Bola_Oyebamiji'),
('bola-tinubu', 'Bola Tinubu', 'Bola_Tinubu', 'Asiwaju Bola Ahmed Adekunle Tinubu GCFR is a Nigerian politician serving as the 16th and current president of Nigeria since 2023. He previously served as the governor of Lagos State from 1999 to 2007 and senator for Lagos West in the Third Republic.', '1952-03-29', null, 'Lagos, British Nigeria', 'LA', 'male', 'All Progressives Congress', 'Richard J. Daley College; Chicago State University (BS)', null, '[{"title": "16th President of Nigeria", "term": "Since 29 May 2023"}, {"title": "Federal Minister of Petroleum Resources", "term": "Since 21 August 2023"}, {"title": "12th Governor of Lagos State", "term": "29 May 1999 – 29 May 2007"}, {"title": "Member of the Nigerian Senate for Lagos West", "term": "5 December 1992 – 17 November 1993"}]', 'wikipedia:person:Bola_Tinubu'),
('boni-haruna', 'Boni Haruna', 'Boni_Haruna', 'Boni Haruna is a Nigerian politician who served as Minister for Youth Development of Nigeria from 2014 to 2015. He previously served as governor of Adamawa State from 1999 to 2007 and was a member of the Peoples Democratic Party (PDP).', '1957-06-12', null, 'Kubi, Michika, British Cameroon (now in Adamawa State, Nigeria)', 'AD', 'male', 'Peoples Democratic Party', null, 'Politician', '[{"title": "Minister of Youth Development", "term": "5 March 2014 – 12 November 2015"}, {"title": "Governor of Adamawa State", "term": "29 May 1999 – 29 May 2007"}]', 'wikipedia:person:Boni_Haruna'),
('bukar-ibrahim', 'Bukar Ibrahim', 'Bukar_Ibrahim', 'Bukar Abba Ibrahim (Walin Gujba) was a Nigerian politician who served as the senator representing the Yobe East senatorial district from 2007 to 2019. He previously served twice as the governor of Yobe State from 1992 to 1993 and from 1999 to 2007.', '1950-10-00', '2024-02-04', null, null, 'male', 'Social Democratic Party', 'Ahmadu Bello University', 'Politician', '[{"title": "Senator for Yobe East", "term": "5 June 2007 – 9 June 2019"}, {"title": "Governor of Yobe State", "term": "29 May 1999 – 29 May 2007"}]', 'wikipedia:person:Bukar_Ibrahim'),
('bukola-saraki', 'Bukola Saraki', 'Bukola_Saraki', 'Abubakar Bukola Saraki MBBS CON is a Nigerian politician who served as the 13th president of the Nigerian Senate from 2015 to 2019. He was elected the President of Nigeria''s 8th Senate on 9 June 2015 under the All Progressives Congress (APC).', '1962-12-19', null, 'London, United Kingdom', null, 'male', 'Peoples Democratic Party', 'Bachelor of Medicine, Bachelor of Surgery, Cheltenham College', 'Physician and Politician', '[{"title": "13th President of the Nigerian Senate", "term": "9 June 2015 – 9 June 2019"}, {"title": "Senator for Kwara Central", "term": "6 June 2011 – 9 June 2019"}, {"title": "Governor of Kwara State", "term": "29 May 2003 – 29 May 2011"}]', 'wikipedia:person:Bukola_Saraki'),
('buruji-kashamu', 'Buruji Kashamu', 'Buruji_Kashamu', 'Buruji Kashamu was a Nigerian politician who served as a Senator representing Ogun East in the 8th National Assembly. Ogun East covers nine local government areas: Ijebu North East, Ijebu North, Ijebu-Ode, Ijebu East, Ikenne, Odogbolu, Remo North, Sagamu, and Ogun Waterside. Senator Kashamu was the vice-chairman of the Senate Committee on States and Local Government.', null, '2020-08-08', 'Ijebu-Igbo, Western Region, British Nigeria', null, 'male', 'People''s Democratic Party', 'Igbobi College; University of Lagos; Pitman College', 'Businessman; politician', '[{"title": "Senator for Ogun East", "term": "9 June 2015 – April 2019 Serving with Lanre Tejuosho Joseph Dada"}, {"title": "Vice-Chairman of the Senate Committee on State and local Governments", "term": "9 June 2015 – April 2019"}]', 'wikipedia:person:Buruji_Kashamu'),
('caleb-mutfwang', 'Caleb Mutfwang', 'Caleb_Mutfwang', 'Caleb Manasseh Mutfwang is a Nigerian lawyer and politician who is the current governor of Plateau State since 2023. He is a former Chairman of Mangu Local Government Area of Plateau State. Mutfwang was sworn in as governor on 29 May 2023.', '1965-03-12', null, null, null, 'male', 'All Progressive Congress', 'School of Preliminary Studies', 'Politician; lawyer', '[{"title": "Governor of Plateau State", "term": "Since 29 May 2023"}]', 'wikipedia:person:Caleb_Mutfwang'),
('celestine-omehia', 'Celestine Omehia', 'Celestine_Omehia', 'Sir Celestine Ngozichim Omehia was the fourth Governor of Rivers State, Nigeria from 29 May 2007 to 25 October 2007. He is a member of the former national governing People''s Democratic Party (PDP). He is married to Mrs. Anthonia Omehia and they have three children (Keturah, Kelechi and Kechikamma).', '1959-09-15', null, null, null, 'male', 'People''s Democratic Party', null, null, '[{"title": "4th Governor of Rivers State", "term": "29 May 2007 – 25 October 2007"}]', 'wikipedia:person:Celestine_Omehia'),
('charles-soludo', 'Charles Soludo', 'Charles_Soludo', 'Prof. Charles Chukwuma Soludo CFR is a Nigerian politician, banker, and economist who has served as the governor of Anambra State since March 2022. He is a former governor and chairman of the board of directors of the Central Bank of Nigeria, from 2004 to 2009.', '1960-07-28', null, 'Aguata, Eastern Region, British Nigeria (now in Anambra State, Nigeria)', 'AN', 'male', 'All Progressives Grand Alliance', null, 'Politician; economist; banker', '[{"title": "Governor of Anambra State", "term": "Since 17 March 2022"}, {"title": "Governor of the Central Bank of Nigeria", "term": "29 May 2004 – 29 May 2009"}]', 'wikipedia:person:Charles_Soludo'),
('chimaroke-nnamani', 'Chimaroke Nnamani', 'Chimaroke_Nnamani', 'Chimaroke Nnamani is a Nigerian medical doctor and politician from Enugu State. He was elected Governor of Enugu State in the 1999 Enugu State gubernatorial election from 1999 to 2007. He subsequently served as a Peoples Democratic Party (PDP) Senator for Enugu East Senatorial District from 2007 to 2011 and was re-elected in 2019.', '1960-05-30', null, 'Port Harcourt, Rivers State, Nigeria', 'RI', 'male', 'Peoples Democratic Party', null, null, '[{"title": "Senator for Enugu East", "term": "11 June 2019 – 11 June 2023"}, {"title": "3rd Governor of Enugu State", "term": "29 May 1999 – 29 May 2007"}]', 'wikipedia:person:Chimaroke_Nnamani'),
('chinwoke-mbadinuju', 'Chinwoke Mbadinuju', 'Chinwoke_Mbadinuju', 'Chinwoke Mbadinuju was a Nigerian politician who served as governor of Anambra State in Nigeria from 29 May 1999 to 29 May 2003. He was elected on the platform of the Peoples Democratic Party (PDP) and served only a single term.', null, '2023-04-11', null, null, 'male', null, 'University of Nigeria', null, '[{"title": "Governor of Anambra State", "term": "29 May 1999 – 29 May 2003"}]', 'wikipedia:person:Chinwoke_Mbadinuju'),
('chris-ngige', 'Chris Ngige', 'Chris_Ngige', 'Chris Nwabueze Ngige is a Nigerian politician and medical doctor who served as minister of Labour and Employment of Nigeria under President Muhammadu Buhari ''s administration from 2015 to 2023. He was elected Senator for Anambra Central Constituency in April 2011. He was the governor of Anambra State in Nigeria from May 2003 to March 2006 under the People''s Democratic Party (PDP).', '1952-08-08', null, null, null, 'male', 'All Progressives Congress', 'University of Nigeria Nsukka', null, '[{"title": "Minister of Labour and Employment Nigeria", "term": "11 November 2015 – 29 May 2023"}, {"title": "Governor of Anambra State", "term": "29 May 2003 – 17 March 2006"}, {"title": "Senator for Anambra Central", "term": "6 June 2011 – 6 June 2015"}]', 'wikipedia:person:Chris_Ngige'),
('dakuku-peterside', 'Dakuku Peterside', 'Dakuku_Peterside', 'Dakuku Adol Peterside is a Nigerian politician. He was formerly the Director General of the Nigerian Maritime Administration and Safety Agency from March 2016 to March 2020. Prior to his role at NIMASA, he was a member of the Nigerian House of Representatives.', null, null, 'Biriye, Opobo Kingdom, Rivers State, Nigeria', 'RI', 'male', 'All Progressive Congress', 'Rivers State University; University of Port Harcourt', 'Politician', '[{"title": "Director General of the Nigerian Maritime Administration and Safety Agency", "term": "10 March 2016 – 4 March 2020"}, {"title": "Member of the House of Representatives of Nigeria", "term": "2011–2015"}, {"title": "Rivers State Commissioner of Works", "term": "2007–2011"}, {"title": "Executive Director of Development and Leadership Institute (DLI)", "term": "2005–2007"}, {"title": "Senior Special Assistant to Governor of Rivers State on Works", "term": "2003–2005"}, {"title": "Chairman Opobo-Nkoro Local Government Area", "term": "2002–2003"}]', 'wikipedia:person:Dakuku_Peterside'),
('danbaba-suntai', 'Danbaba Suntai', 'Danbaba_Suntai', 'Danbaba Danfulani Suntai was a Nigerian pharmacist and politician who served as the governor of Taraba State from 2007 to 2015. He was involved in a self piloted aircrash on 25 October 2012, which left him incapacitated for the remainder of his term.', '1961-06-30', '2017-06-28', 'Suntai, Bali, Northern Region (now in Taraba State), Nigeria', 'TA', 'male', 'Peoples Democratic Party', null, 'Politician; pharmacist', '[{"title": "Governor of Taraba State", "term": "29 May 2007 – 29 May 2015"}]', 'wikipedia:person:Danbaba_Suntai'),
('dapo-abiodun', 'Dapo Abiodun', 'Dapo_Abiodun', 'Adedapo Oluseun Abiodun MFR CON is a Nigerian businessman and politician, who has served as Governor of Ogun State since May 2019. Currently a member of the All Progressives Congress, Abiodun first entered politics during the aborted Abacha transition in 1998 and remained active in politics until being elected governor in 2019.', '1960-05-29', null, 'Iperu, Ogun State, Western Region, Colonial Nigeria (now in Ogun State, Nigeria)', 'OG', 'male', 'All Progressives Congress', null, 'Politician; businessman', '[{"title": "Governor of Ogun State", "term": "Since 29 May 2019"}]', 'wikipedia:person:Dapo_Abiodun'),
('dapo-sarumi', 'Dapo Sarumi', 'Dapo_Sarumi', 'Dapo Sarumi is a Nigerian politician from Lagos State. He was the former minister for Information. In 1991, he contested the Social Democratic Party (Nigeria) gubernatorial primary under the People''s Front faction of the SDP led by Shehu Musa Yar''adua, members of the PF included Yomi Edu, Bola Tinubu, Abdullahi Aliyu Sumaila, Abubakar Koko, Babalola Borishade, Umaru Musa Yar''adua, Sabo Bakin Zuwo, and Rabiu Musa Kwankwaso but he was later dis-qualified.', null, null, 'Epe, Lagos State', 'LA', 'male', 'Social Democratic Party', null, null, '[{"title": "Federal Minister for Communication", "term": "June 1999 – January 2001"}]', 'wikipedia:person:Dapo_Sarumi'),
('darius-ishaku', 'Darius Ishaku', 'Darius_Ishaku', 'Darius Dickson Ishaku is a Nigerian architect, urban planner, university lecturer and politician. He is a member of the Peoples Democratic Party and served as the governor of Taraba State from May 2015 to May 2023.', '1954-07-30', null, 'Lupwe, Northern Region, British Nigeria (now in Taraba State, Nigeria)', 'TA', 'male', 'Peoples Democratic Party', 'St. Paul''s College Kufena, Zaria; Ahmadu Bello University', 'Politician; architect', '[{"title": "Governor of Taraba State", "term": "29 May 2015 – 29 May 2023"}]', 'wikipedia:person:Darius_Ishaku'),
('dauda-lawal', 'Dauda Lawal', 'Dauda_Lawal', 'Dauda Lawal is a Nigerian banker and politician who is the governor of Zamfara state. He was elected under the platform of the Peoples Democratic Party (PDP) in the 2023 Nigerian gubernatorial elections defeating the incumbent Governor Bello Matawalle of the APC.', '1965-09-02', null, 'Gusau, Northern Region (now in Zamfara State), Nigeria', 'ZA', 'male', 'All Progressives Congress', 'BSC, Msc. Political Science (ABU); PhD. Business Administration (UDUS)', 'Politician; banker', '[{"title": "Governor of Zamfara State", "term": "Since 29 May 2023"}]', 'wikipedia:person:Dauda_Lawal'),
('david-lyon', 'David Lyon', 'David_Lyon_(Nigerian_politician)', 'David Lyon Perewonrimi is a Nigerian politician and the former governorship candidate of the All Progressives Congress in the 2019 Bayelsa gubernatorial election. He was declared winner of the election, but a day to his swearing-in as governor, his election was invalidated by the Supreme Court of Nigeria. The Apex court ruled that his running mate Degi Eremienyo Wangagra submitted a fake certificate to the Independent National Electoral Commission, while ordering that Douye Diri of People''s Democratic Party who came second in the election be issued a certificate of return, which would make him governor-elect.', '1970-12-20', null, 'Olugbobiri, Southern Ijaw, Bayelsa State, Nigeria', 'BY', 'male', 'All Progressives Congress', null, null, '[]', 'wikipedia:person:David_Lyon_(Nigerian_politician)'),
('david-ombugadu', 'David Ombugadu', 'David_Ombugadu', 'David Emmanuel Ombugadu is a Nigerian politician who was a Member of House of Representatives Nigeria representing Akwanga, Wamba and Nassarawa Eggon federal constituency from 2011 to 2019. He contested as the governorship candidate of the Peoples Democratic Party (Nigeria) (PDP) for Nasarawa state in the 2019 and 2023 general elections.', null, null, null, null, 'male', null, null, null, '[]', 'wikipedia:person:David_Ombugadu'),
('david-umahi', 'David Umahi', 'David_Umahi', 'David Nweze Umahi CON is a Nigerian politician who is the Minister of Works of Nigeria. He previously was the senator representing Ebonyi South senatorial district from June to August 2023, and as the governor of Ebonyi State from 2015 to 2023; and deputy governor from 2011 to 2015.', '1963-07-25', null, 'Uburu, Eastern Region (now in Ebonyi State), Nigeria', 'EB', 'male', 'All Progressives Congress', 'Government Secondary School, Afikpo; Anambra State University', 'Politician', '[{"title": "Minister of Works", "term": "Since 21 August 2023"}, {"title": "Senator for Ebonyi South", "term": "13 June 2023 – August 2023"}, {"title": "Governor of Ebonyi State", "term": "29 May 2015 – 29 May 2023"}, {"title": "Deputy Governor of Ebonyi State", "term": "29 May 2011 – 29 May 2015"}]', 'wikipedia:person:David_Umahi'),
('david-umaru', 'David Umaru', 'David_Umaru', 'David Umaru is a Nigerian Politician, and was the Senator representing Niger East Senatorial District of Niger State at the Nigerian 7th National Assembly and 8th National Assembly.', '1959-07-26', null, 'Kuta, Shirorro Niger state', null, 'male', 'All Progressive Congress', 'Ahmadu Bello University', 'Politician; Lawyer', '[{"title": "Senator of the Federal Republic of Nigeria from Niger East Senatorial District", "term": "June 2011 – November 2019"}]', 'wikipedia:person:David_Umaru'),
('diepreye-alamieyeseigha', 'Diepreye Alamieyeseigha', 'Diepreye_Alamieyeseigha', 'Diepreye Solomon Peter "D.S.P." Alamieyeseigha was a Nigerian politician who was the first civilian Governor of Bayelsa State in Nigeria from 29 May 1999 to 9 December 2005.', null, '2015-10-10', 'Amassoma, Southern Region, British Nigeria (now Bayelsa State, Nigeria)', 'BY', 'male', null, null, null, '[{"title": "5th Governor of Bayelsa", "term": "29 May 1999 – 9 December 2005"}]', 'wikipedia:person:Diepreye_Alamieyeseigha'),
('dikko-umar-radda', 'Dikko Umar Radda', 'Dikko_Umar_Radda', 'Dikko Umar Radda thumb is a Nigerian economist and politician. He was elected governor of Katsina State in the 2023 Nigerian gubernatorial elections. He previously served as the director-general of the Small and Medium Enterprises Development Agency of Nigeria (SMEDAN).', '1969-09-10', null, 'Dutsin-Ma, North-Central State (now in Katsina State), Nigeria', 'KT', 'male', 'All Progressives Congress', 'Radda Primary School; Zaria Teachers College', 'Politician; economist', '[{"title": "Governor of Katsina State", "term": "Since 29 May 2023"}, {"title": "Chairman of Charanchi Local Government Area", "term": "2003–2008"}]', 'wikipedia:person:Dikko_Umar_Radda'),
('dimeji-bankole', 'Dimeji Bankole', 'Dimeji_Bankole', 'Sabur Oladimeji \"Dimeji\" Bankole is a Nigerian politician who served as the 11th Speaker of the House of Representatives of Nigeria. He was the Action Democratic Party candidate in the 2019 Ogun State gubernatorial election but lost to the All Progressives Congress candidate, Dapo Abiodun.', '1969-11-14', null, 'Abeokuta, Ogun State, Nigeria', 'OG', 'male', 'All Progressives Congress', 'University of Reading (BA); Harvard University (MPA)', 'Politician; businessman; economist', '[{"title": "11th Speaker of the House of Representatives of Nigeria", "term": "1 November 2007 – 6 June 2011"}, {"title": "Member of the House of Representatives of Nigeria from Ogun", "term": "3 June 2003 – 6 June 2011"}]', 'wikipedia:person:Dimeji_Bankole'),
('dino-melaye', 'Dino Melaye', 'Dino_Melaye', 'Barrister Daniel Dino Melaye is a Nigerian lawyer (having recently graduated from a law degree program in 2025. He is a former senator and a former member of the National Assembly of Nigeria, representing the Kogi West Senatorial District in Kogi State.', '1974-01-07', null, 'Kano, Nigeria', 'KN', 'male', 'African Democratic Congress', 'Ahmadu Bello University', null, '[{"title": "Senator", "term": "June 2015 – 11 October 2019"}]', 'wikipedia:person:Dino_Melaye'),
('donald-duke', 'Donald Duke', 'Donald_Duke', 'Donald J. Duke is a Nigerian politician. He was the Governor of Cross River State, Nigeria from 29 May 1999 to 29 May 2007. He is currently a member of the People''s Redemption Party (PRP) and was the 2019 Nigeria Presidential candidate for Social Democratic Party, SDP. He is currently the presidential candidate for the 2027 Nigeria general election under the People''s Redemption Party.', '1961-09-30', null, 'Calabar, Cross River State, Nigeria', 'CR', 'male', 'Peoples Redemption Party', 'Ahmadu Bello University, Zaria Class of 1982; University of Pennsylvania Class of 1984', null, '[{"title": "Commissioner for Finance and Planning", "term": "1992-1993"}, {"title": "Governor of Cross River State", "term": "29 May 1999 – 29 May 2007"}]', 'wikipedia:person:Donald_Duke'),
('douye-diri', 'Douye Diri', 'Douye_Diri', 'Douye Diri is a Nigerian politician who has served as the governor of Bayelsa State since 2020. He was the senator representing Bayelsa Central Senatorial District from 2019 to 2020 in the 9th National Assembly.', '1959-06-04', null, null, null, 'male', 'All Progressives Congress', 'College of Education, Port Harcourt; University of Port Harcourt (B. Ed)', 'Politician', '[{"title": "12th Governor of Bayelsa State", "term": "Since 14 February 2020"}, {"title": "Senator for Bayelsa Central", "term": "11 June 2019 – 11 February 2020"}]', 'wikipedia:person:Douye_Diri'),
('emeka-ihedioha', 'Emeka Ihedioha', 'Emeka_Ihedioha', 'Chukwuemeka Ihedioha is a Nigerian politician and businessman who served as governor of Imo State from 2019 to 2020. He was removed from office on 14 January 2020, by the Supreme Court of Nigeria which declared the APC candidate (Hope Uzodinma) the authentic winner of the 2019 gubernatorial election. He was deputy speaker of the House of Representatives of Nigeria from 2011 to 2015.', '1965-03-24', null, 'Aboh Mbaise, Eastern Region, Nigeria (now in Imo State)', 'IM', 'male', 'African Democratic Congress', null, 'Politician; businessman', '[{"title": "6th Governor of Imo State", "term": "29 May 2019 – 15 January 2020"}, {"title": "Deputy Speaker of the House of Representatives of Nigeria", "term": "6 June 2011 – 6 June 2015"}, {"title": "House Chief Whip", "term": "November 2007 – 6 June 2011"}, {"title": "Member of the House of Representatives of Nigeria from Imo", "term": "3 June 2003 – 6 June 2015"}]', 'wikipedia:person:Emeka_Ihedioha'),
('emmanuel-bwacha', 'Emmanuel Bwacha', 'Emmanuel_Bwacha', 'Emmanuel Bwacha CON is a Nigerian politician who served as the senator representing the Taraba South senatorial district from 2011 to 2023. He was elected on the platform of the Peoples Democratic Party (PDP) in 2011, and was reelected under the same party in the 2015 and 2019 general elections.', '1962-12-15', null, 'Donga, Northern Region (now in Taraba State), Nigeria', 'TA', 'male', 'All Progressives Congress', null, 'Politician', '[{"title": "Senator for Taraba South", "term": "6 June 2011 – 11 June 2023 Serving with Shuaibu Isa Lau Yusuf Abubakar Yusuf"}, {"title": "Deputy Senate Minority Leader", "term": "2 July 2019 – 3 February 2022"}, {"title": "Vice-Chairman of the Senate Committee on Work", "term": "2 July 2019 – 11 June 2023"}, {"title": "Member of the House of Representatives of Nigeria from Taraba", "term": "3 June 2003 – 5 June 2007"}]', 'wikipedia:person:Emmanuel_Bwacha'),
('emmanuel-uduaghan', 'Emmanuel Uduaghan', 'Emmanuel_Uduaghan', 'Emmanuel Eweta Uduaghan was a Nigerian politician and medical doctor who served as Governor of Delta State from 2007 to 2015. He assumed office via an inconclusive election on 29 May 2007 and was a member of the People''s Democratic Party (PDP). He was reelected and sworn in for a second tenure in 2011.', '1954-10-22', '2026-10-19', 'Warri North, Delta State, Nigeria', 'DE', 'male', 'PDP', 'University of Benin, Nigeria', null, '[{"title": "3rd Governor of Delta State", "term": "29 May 2007 – 29 May 2015"}]', 'wikipedia:person:Emmanuel_Uduaghan'),
('eyitayo-jegede', 'Eyitayo Jegede', 'Eyitayo_Jegede', 'Eyitayo Jegede SAN, is a Nigerian legal practitioner and politician. He was the Peoples Democratic Party (PDP) candidate in the 2016 and 2020 Ondo State gubernatorial elections.', null, null, 'Ondo State, Nigeria', 'ON', 'male', null, null, 'Lawyer', '[{"title": "Attorney General and Commissioner for Justice in Ondo State", "term": "2008–2016"}]', 'wikipedia:person:Eyitayo_Jegede'),
('fatai-akinade-akinbade', 'Fatai Akinade Akinbade', 'Fatai_Akinade_Akinbade', 'Alhaji Fatai Akinade Akinbade is a Nigerian politician and the former Secretary to the State Government in Osun State. He was a contender to become the People''s Democratic Party (PDP) candidate for governorship of Osun State in the April 2011 elections.', null, null, null, null, 'male', null, null, null, '[]', 'wikipedia:person:Fatai_Akinade_Akinbade'),
('francis-nwifuru', 'Francis Nwifuru', 'Francis_Nwifuru', 'Francis Ogbonna Erishi Nwifuru is a Nigerian politician and lawyer who is the current governor of Ebonyi State since 2023. He previously served as speaker of the Ebonyi State House of Assembly from June 2015 to May 2023. He hails from Oferekpe Agbaja in Izzi local government area of Ebonyi State.', '1975-02-25', null, 'Oferekpe Agbaja, Izzi, Ebonyi State, Nigeria', 'EB', 'male', null, null, 'Politician; lawyer; entrepreneur', '[{"title": "6th Governor of Ebonyi State", "term": "Since 29 May 2023"}, {"title": "Speaker of the Ebonyi State House of Assembly", "term": "9 June 2015 – 29 May 2023"}]', 'wikipedia:person:Francis_Nwifuru'),
('funsho-williams', 'Funsho Williams', 'Funsho_Williams', 'Anthony Olufunsho Williams was a Nigerian politician from Lagos State, who served as former Commissioner under Colonel Olagunsoye Oyinlola, the then military administrator of the state. He was assassinated on 27 July 2006, at age 58.', '1948-05-09', '2006-07-27', 'Lagos, Lagos State, Nigeria', 'LA', 'male', 'People''s Democratic Party', 'St Gregory''s College, Lagos; University of Lagos.', null, '[]', 'wikipedia:person:Funsho_Williams'),
('gabriel-suswam', 'Gabriel Suswam', 'Gabriel_Suswam', 'Gabriel Torwua Suswam is a Nigerian politician and former Governor of Benue State. He represented Benue North-East Senatorial district in the 9th National Assembly of the Federal Republic of Nigeria.', '1964-11-15', null, 'Anyiin, Logo LGA of Benue State', 'BE', 'male', null, 'University of Lagos', null, '[{"title": "Former Governor of Benue State", "term": "29 May 2007 – 29 May 2015"}]', 'wikipedia:person:Gabriel_Suswam'),
('garba-yakubu-lado', 'Garba Yakubu Lado', 'Garba_Yakubu_Lado', 'Garba Yakubu Lado Danmarke pronunciation is a Nigerian businessman who became a Member of the House of Representatives (2003–2007) and was elected a Federal Senator in April 2007 for Katsina South constituency of Katsina State as a member of the People''s Democratic Party (PDP).', null, null, null, null, 'male', 'People''s Democratic Party', null, null, '[{"title": "Senator of the Federal Republic of Nigeria from Katsina State", "term": "29 May 2007 – June 2011"}]', 'wikipedia:person:Garba_Yakubu_Lado'),
('gbadebo-rhodes-vivour', 'Gbadebo Rhodes-Vivour', 'Gbadebo_Rhodes-Vivour', 'Chief Gbadebo Patrick Chinedu Rhodes-Vivour, also known as G.R.V., is a Nigerian architect, entrepreneur and politician. He was the gubernatorial candidate of the Labour Party for Lagos State in the 2023 gubernatorial election where he finished runner-up, losing to incumbent governor, Babajide Sanwo-Olu. He was the senatorial candidate of the Peoples Democratic Party for the Lagos West senatorial district in the 2019 Senate elections.', '1983-03-08', null, 'Lagos Island, Lagos, Nigeria', 'LA', 'male', 'Labour Party', 'Bachelor of Architecture; Master of Architecture; Master of Research and Public Policy', 'Architect; politician; activist', '[]', 'wikipedia:person:Gbadebo_Rhodes-Vivour'),
('gbenga-daniel', 'Gbenga Daniel', 'Gbenga_Daniel', 'Gbenga Daniel is a Nigerian politician who has served as Senator for Ogun East since 2023. He previously served as governor of Ogun State from 2003 to 2011.', '1956-04-06', null, 'Ibadan, Western Region, British Nigeria (now in Oyo State, Nigeria)', 'OY', 'male', 'All Progressives Congress', 'University of Lagos (BSC); Lagos Business School (MBA)', 'Politician; businessman', '[{"title": "Senator for Ogun East", "term": "Since 13 June 2023"}, {"title": "Governor of Ogun State", "term": "29 May 2003 – 29 May 2011"}]', 'wikipedia:person:Gbenga_Daniel'),
('gbenga-olawepo-hashim', 'Gbenga Olawepo-Hashim', 'Gbenga_Olawepo-Hashim', 'Gbenga Toyosi Olawepo is a Nigerian human rights activist and businessman. Olawepo first was recognized as an anti-apartheid activist; he and three other students'' leaders of the University of Lagos were clamped into the over-crowded Nigeria Police cell in April 1989 after an anti-apartheid protest. The military regime that was growing increasingly repressive and intolerant of freedom of expression in Nigeria then ordered the detention of the student activist. The Education Editor of Guardian Express – Joe Idika- published an exclusive report on the plight of the quartet in what was an exposé on the deplorable condition under which detainees are held in the Nigerian Police facilities.', null, null, 'Yelwa, Kebbi state', 'KE', 'male', 'Accord Party', 'Cherubim and Seraphim College, Ilorin. University of Lagos, Kwara College of Technology', 'Politician, Human rights activist, Businessman', '[]', 'wikipedia:person:Gbenga_Olawepo-Hashim'),
('gboyega-nasir-isiaka', 'Gboyega Nasir Isiaka', 'Gboyega_Nasir_Isiaka', 'Gboyega Nasir Isiaka is a Nigerian politician and a member of the Nigerian House of Representatives. He represents the Yewa North / Imeko-Afon Federal Constituency in Ogun State.', null, null, null, null, null, null, null, 'Politician', '[]', 'wikipedia:person:Gboyega_Nasir_Isiaka'),
('gboyega-oyetola', 'Gboyega Oyetola', 'Gboyega_Oyetola', 'Adegboyega Isiaka Oyetola CON is a Nigerian politician who is the current minister of Marine and Blue Economy. He served as governor of Osun State from 2018 to 2022.', '1954-09-29', null, 'Iragbiji, Southern Region, British Nigeria (now in Osun State, Nigeria)', 'OS', 'male', 'All Progressives Congress', 'University of Lagos', 'Politician', '[{"title": "Minister of Marine and Blue Economy", "term": "Since 21 August 2023"}, {"title": "Governor of Osun State", "term": "27 November 2018 – 27 November 2022"}, {"title": "Chief of Staff to the Governor of Osun State", "term": "2011–2018"}]', 'wikipedia:person:Gboyega_Oyetola'),
('george-akume', 'George Akume', 'George_Akume', 'George Akume CON is a Nigerian politician who is the 21st and current Secretary to the Government of the Federation. He served as Minister of Special Duties and Inter-Governmental Affairs from 2019 to 2023, during the administration of President Muhammadu Buhari. He was the Senator representing Benue North-West Senatorial District between 2007 and 2019. He was also the Minority Leader of the Senate from June 2011 to June 2015. He served as the Governor of Benue State from May 1999 to May 2007.', '1953-12-27', null, null, null, 'male', 'All Progressives Congress', 'University of Ibadan', 'Politician', '[{"title": "Secretary to the Government of the Federation", "term": "Since 7 June 2023"}, {"title": "Minister of Special Duties and Inter-Governmental Affairs", "term": "21 August 2019 – 29 May 2023"}, {"title": "Senator for Benue North-West", "term": "5 June 2007 – 9 June 2019"}, {"title": "Senate Minority Leader", "term": "6 June 2011 – 6 June 2015"}, {"title": "Governor of Benue State", "term": "29 May 1999 – 29 May 2007"}]', 'wikipedia:person:George_Akume'),
('godswill-akpabio', 'Godswill Akpabio', 'Godswill_Akpabio', 'Chief Godswill Obot Akpabio GCON is a Nigerian lawyer and politician who has been serving as the 15th president of the Nigerian Senate since 2023. He was first elected as Senator representing Akwa Ibom North-West Senatorial District in 2015, lost in the 2019 senatorial elections and won in the 2023 elections. He also served as minister for Niger Delta Affairs from 2019 up till 2022 when he resigned to seek re-election into the Nigerian senate. He had previously served as the Governor of Akwa Ibom State from 2007 to 2015.', '1962-12-09', null, 'Ukana, Ikot Ntuen, Essien Udim, Eastern Region, Nigeria (now in Akwa Ibom State)', 'AK', 'male', 'All Progressives Congress', 'University of Calabar', 'Politician; lawyer', '[{"title": "15th President of the Nigerian Senate", "term": "Since 13 June 2023"}, {"title": "Senator for Akwa Ibom North-West", "term": "Since 13 June 2023"}, {"title": "Minister for Niger Delta Affairs", "term": "21 August 2019 – 11 May 2022"}, {"title": "Senate Minority Leader", "term": "28 July 2015 – 7 August 2018"}, {"title": "3rd Governor of Akwa Ibom State", "term": "29 May 2007 – 29 May 2015"}]', 'wikipedia:person:Godswill_Akpabio'),
('godwin-ezeemo', 'Godwin Ezeemo', 'Godwin_Ezeemo', 'Godwin Chukwunaenye Ezeemo is a Nigerian businessman and politician, chairman of The Orient Group of companies and a member of the Progressive Peoples Alliance.', null, null, 'Umuchu, in Aguata Local Government Area.', null, 'male', null, 'Federal polytechnic Ilaro Ogun state. MARKETING (ND, HND)', 'CEO Orient Media group of companies', '[]', 'wikipedia:person:Godwin_Ezeemo'),
('godwin-maduka', 'Godwin Maduka', 'Godwin_Maduka', 'Godwin Maduka, is a Nigerian-American doctor, businessman and philanthropist. He is the founder of Las Vegas Pain Institute and Medical Center. In 2008, he played a major role in the renaming of his hometown, from Nkerehi to Umuchukwu.', null, null, 'Nkerehi, Eastern Region, British Nigeria (now Nkerehi, Anambra, Nigeria)', 'AN', 'male', null, null, 'Doctor; businessman; philanthropist', '[]', 'wikipedia:person:Godwin_Maduka'),
('godwin-obaseki', 'Godwin Obaseki', 'Godwin_Obaseki', 'Godwin Nogheghase Obaseki is a Nigerian politician and businessman who served as the governor of Edo State from 2016 to 2024.', '1957-07-01', null, 'Benin City, Western Region, British Nigeria', null, 'male', 'Peoples Democratic Party', 'Eghosa Grammar School, Benin City; University of Ibadan; Columbia University', 'Politician; businessman', '[{"title": "Governor of Edo State", "term": "12 November 2016 – 12 November 2024"}]', 'wikipedia:person:Godwin_Obaseki'),
('goodluck-jonathan', 'Goodluck Jonathan', 'Goodluck_Jonathan', 'Goodluck Ebele Azikiwe Jonathan GCFR GCON is a Nigerian politician who served as the president of Nigeria from 2010 to 2015. He lost the 2015 presidential election to former military head of state General Muhammadu Buhari and was the first incumbent president in Nigerian history to lose re-election.', '1957-11-20', null, 'Ogbia, Eastern Region, British Nigeria (now Ogbia, Bayelsa State, Nigeria)', 'BY', 'male', 'Peoples Democratic Party', 'University of Port Harcourt (BS, MS, PhD)', 'Politician', '[{"title": "14th President of Nigeria", "term": "6 May 2010 – 29 May 2015 Acting: 9 February 2010 – 6 May 2010"}, {"title": "12th Vice President of Nigeria", "term": "29 May 2007 – 6 May 2010"}, {"title": "6th Governor of Bayelsa", "term": "9 December 2005 – 29 May 2007"}, {"title": "Deputy Governor of Bayelsa", "term": "29 May 1999 – 9 December 2005"}]', 'wikipedia:person:Goodluck_Jonathan'),
('great-ogboru', 'Great Ogboru', 'Great_Ogboru', 'Great Ovedje Ogboru is a Nigerian businessman and politician who was the gubernatorial candidate for the Alliance of Democracy, the Democratic Peoples'' Party and the Labour Party in the 2003, 2007 and 2015 Delta State governorship elections. He was also the gubernatorial nominee for the All Progressives Congress (APC) in the 2019 Delta State governorship elections.', '1958-04-10', null, 'Port Harcourt, Nigeria', null, 'male', null, 'The Chartered Institute of Marketing (BA); Huron University USA in London (MBA); University of Kent (MA)', null, '[]', 'wikipedia:person:Great_Ogboru'),
('gregory-ibe', 'Gregory Ibe', 'Gregory_Ibe', 'Gregory Ikechukwu Ibe was a Nigerian industrialist, academic and politician. He was the founder and Chancellor of Gregory University, Uturu, and the visionary behind Innov8 Hub, a focal point for innovation and startup incubation in Abuja.', '1963-12-10', '2026-10-18', 'Kaduna, Northern Nigeria, Nigeria', 'KD', 'male', 'All Progressives Grand Alliance', null, 'Academic; Industrialist; Politician', '[]', 'wikipedia:person:Gregory_Ibe'),
('gyang-pwajok', 'Gyang Pwajok', 'Gyang_Pwajok', 'Gyang Nyam Shom (GNS) Pwajok was a Nigerian politician and a member of the People''s Democratic Party (PDP). Pwajok was the youngest national Senator during the upper chamber''s 7th Assembly, which was in session from 2011 to 2015. He was the 2015 PDP candidate for Governor of Plateau State, but narrowly lost the Plateau gubernatorial election to Simon Lalong of the All Progressives Congress on April 11, 2015.', '1966-03-15', '2015-10-28', null, null, 'male', null, null, null, '[{"title": "Senator of the Federal Republic of Nigeria", "term": "2012–2015"}, {"title": "Chief of staff to Governor Jonah David Jang", "term": "2011–2012"}]', 'wikipedia:person:Gyang_Pwajok'),
('halliru-dauda-jika', 'Halliru Dauda Jika', 'Halliru_Dauda_Jika', 'Halliru Dauda Jika was born in 1976 in Bauchi State, Nigeria. He is a businessman and a politician. He was once a member and shortly the speaker of Bauchi State house of assembly, member house of representatives and former senate member representing Bauchi Central. He is also known as Dokaji.', null, null, null, null, 'male', 'All Progressives Congress', null, 'Politician', '[{"title": "House of Representatives", "term": "2015–2019"}, {"title": "Senator Bauchi Central Bauchi State", "term": "2019–2023"}]', 'wikipedia:person:Halliru_Dauda_Jika'),
('henry-seriake-dickson', 'Henry Seriake Dickson', 'Henry_Seriake_Dickson', 'Henry Seriake Dickson CON is a Nigerian lawyer and politician. He has been the Senator representing Bayelsa West senatorial District since 2020 in the 9th National Assembly and also from 2023 in the 10th Assembly. He was the governor of Bayelsa State from 14 February 2012 to 14 February 2020. He was a member of the House of Representatives from 2007 until 2012.', '1966-01-28', null, 'Sagbama, Eastern Region, Nigeria (now in Bayelsa State)', 'BY', 'male', 'Nigeria Democratic Congress', 'Rivers State University of Science and Technology (LL.B.); Nigerian Law School', 'Politician, lawyer', '[{"title": "Senator for Bayelsa West", "term": "Since 15 December 2020"}, {"title": "11th Governor of Bayelsa State", "term": "14 February 2012 – 14 February 2020"}, {"title": "Member of the House of Representatives of Nigeria", "term": "5 June 2007 – 13 February 2012"}, {"title": "Attorney General of Bayelsa State", "term": "2006–2007"}]', 'wikipedia:person:Henry_Seriake_Dickson'),
('herman-hembe', 'Herman Hembe', 'Herman_Hembe', 'Herman Iorwase Hembe is a Nigerian politician and lawyer from Konshisha local government area of Benue State in north central Nigeria who serves as a member of the 9th Assembly in the House of Representatives of Nigeria where he represents Vandeikya/Konshisha Federal Constituency. Hembe is the flagbearer of the Labour party in the 2023 Benue governorship election, having previously contested unsuccessfully under the All Progressives Congress (APC).', '1975-06-22', null, 'Zaria, Kaduna State, Nigeria', 'KD', 'male', null, null, 'Politician, lawyer', '[{"title": "Member of the House of Representatives", "term": "2011–2019"}]', 'wikipedia:person:Herman_Hembe'),
('hope-uzodimma', 'Hope Uzodimma', 'Hope_Uzodimma', 'Hope Odidika Uzodimma is a Nigerian politician who has served as the governor of Imo State since 2020. On 14 January 2020, the Supreme Court of Nigeria declared Uzodimma of the All Progressives Congress (APC) winner of the 2019 governorship poll in Imo State, nullifying the election of the then-incumbent governor Emeka Ihedioha.', '1958-12-12', null, 'Omuma, Eastern Region, British Nigeria (now in Imo State, Nigeria)', 'IM', 'male', 'All Progressives Congress', 'Federal University of Technology Owerri', 'Politician', '[{"title": "Governor of Imo State", "term": "Since 15 January 2020"}, {"title": "Senator for Imo West", "term": "6 June 2011 – 9 June 2019"}]', 'wikipedia:person:Hope_Uzodimma'),
('hyacinth-alia', 'Hyacinth Alia', 'Hyacinth_Alia', 'Hyacinth Iormem Alia is a Nigerian Catholic cleric and politician who has been a serving governor of Benue State since 29 May 2023.', '1966-05-15', null, 'Mbangur, Mbadede, Vandeikya, Benue State, Nigeria', 'BE', 'male', 'All Progressives Congress', null, 'Politician, Catholic priest', '[{"title": "19th Governor of Benue State", "term": "Since 29 May 2023"}]', 'wikipedia:person:Hyacinth_Alia'),
('ibikunle-amosun', 'Ibikunle Amosun', 'Ibikunle_Amosun', 'Ibikunle Amosun is a Nigerian politician, former governor of Ogun State and two-term senator of the Federal Republic of Nigeria. He first served as an elected senator for Ogun Central district of Ogun State, Nigeria from June 2003 to June 2007, and reelected in 2019. After an unsuccessful bid for governor of Ogun State in April 2007, he was elected governor of the state on the Action Congress of Nigeria (ACN) platform in 2011. He contested again for a second term as governor under the All Progressives Congress and after winning the election, was sworn into office on 29 May 2015.', '1958-01-25', null, 'Nigeria', null, 'male', 'All Progressives Congress', null, null, '[{"title": "Senator for Ogun Central", "term": "11 June 2019 – 11 June 2023"}, {"title": "Governor of Ogun State", "term": "29 May 2011 – 29 May 2019"}]', 'wikipedia:person:Ibikunle_Amosun'),
('ibrahim-gaidam', 'Ibrahim Gaidam', 'Ibrahim_Gaidam', 'Ibrahim Gaidam is a Nigerian politician and the current Minister of Police Affairs since 2023. He previously served as senator representing the Yobe East senatorial district from 2019 to 2023, and as governor of Yobe State from 2009 to 2019.', '1956-09-15', null, 'Bukarti, Yunusari, Northern Region, British Nigeria (now in Yobe State, Nigeria)', 'YO', 'male', 'All Progressive Congress', null, 'Politician', '[{"title": "Minister of Police Affairs", "term": "Since 21 August 2023"}, {"title": "Senator for Yobe East", "term": "11 June 2019 – 21 August 2023"}, {"title": "Governor of Yobe State", "term": "27 January 2009 – 29 May 2019"}, {"title": "Deputy Governor of Yobe State", "term": "29 May 2007 – 27 January 2009"}]', 'wikipedia:person:Ibrahim_Gaidam'),
('ibrahim-hassan-dankwambo', 'Ibrahim Hassan Dankwambo', 'Ibrahim_Hassan_Dankwambo', 'Ibrahim Hassan Dankwambo is a Nigerian politician who has served as senator for Gombe North since 2023. He previously served as governor of Gombe State from 2011 to 2019. He is a former Accountant-General of the Federation.', '1962-04-04', null, 'Gombe, Nigeria', 'GO', 'male', 'Peoples Democratic Party', null, 'Politician; accountant', '[{"title": "Senator for Gombe North", "term": "Since 13 June 2023"}, {"title": "Governor of Gombe State", "term": "29 May 2011 – 29 May 2019"}]', 'wikipedia:person:Ibrahim_Hassan_Dankwambo'),
('ibrahim-idris', 'Ibrahim Idris', 'Ibrahim_Idris', 'Ibrahim Idris was a Nigerian politician and businessman who served as the governor of Kogi State from 2003 to 2008 and from 2008 to 2012. He was a member of the Peoples Democratic Party (PDP).', '1949-01-03', '2026-09-20', 'Idah, Northern Region, Colony and Protectorate of Nigeria (now in Kogi State, Nigeria)', 'KO', 'male', 'Peoples Democratic Party', null, 'Politician; businessman', '[{"title": "Governor of Kogi State", "term": "5 April 2008 – 26 January 2012"}]', 'wikipedia:person:Ibrahim_Idris'),
('ibrahim-saminu-turaki', 'Ibrahim Saminu Turaki', 'Ibrahim_Saminu_Turaki', 'Ibrahim Saminu Turaki is a Nigerian actuary and politician who served as the governor of Jigawa State from 1999 to 2007. Prior to that, he was the Jigawa state chairman of the defunct Social Democratic Party (SDP) and United Nigeria Congress Party (UNCP). He was the senator representing Jigawa North-West senatorial district from 2007 to 2011.', '1963-07-14', null, 'Kazaure, Northern Region (now in Jigawa State), Nigeria', 'JI', 'male', 'Peoples Democratic Party', 'Ahmadu Bello University', 'Politician; actuary; public figure', '[{"title": "Senator for Jigawa North-West", "term": "5 June 2007 – 6 June 2011"}, {"title": "Governor of Jigawa State", "term": "29 May 1999 – 29 May 2007"}]', 'wikipedia:person:Ibrahim_Saminu_Turaki'),
('ibrahim-shekarau', 'Ibrahim Shekarau', 'Ibrahim_Shekarau', 'Ibrahim Shekarau is a former Nigerian minister of education and two-term Governor of Kano State in Nigeria. He was elected in April 2003 and re-elected in April 2007. Formerly he''s a member of the Peoples Democratic Party (PDP). He was one of the candidates who aspired to become president in the Nigerian general elections of 2011. He joined the All Progressives Congress (APC) in 2026 and became the party''s candidate for Kano Central in the 2027 Nigerian general election.', '1955-11-05', null, 'Kurmawa', null, 'male', 'PDP', 'Ahmadu Bello University', 'Civil Servant / Politician', '[{"title": "Nigerian Senator from Kano Central", "term": "11 June 2019 – 11 June 2023"}, {"title": "Minister of Education", "term": "9 July 2014 – 2015"}, {"title": "Kano State Governor", "term": "29 May 2003 – 29 May 2011"}]', 'wikipedia:person:Ibrahim_Shekarau'),
('ibrahim-shema', 'Ibrahim Shema', 'Ibrahim_Shema', 'Ibrahim Shehu Shema born 22 September 1957) is a Nigerian lawyer and politician who was elected as a Governor of the north western State of Katsina during the 2007 general elections.', '1957-09-22', null, 'Dutsin-Ma, Katsina State, Federation of Nigeria', 'KT', 'male', 'All Progressives Congress', 'LLB (1983), MBA (1998)', 'Law', '[{"title": "Governor of Katsina State", "term": "29 May 2007 – 29 May 2015"}]', 'wikipedia:person:Ibrahim_Shema'),
('idris-wada', 'Idris Wada', 'Idris_Wada', 'Idris Ichala Wada is a Nigerian retired pilot and politician who served as governor of Kogi State from 2012 to 2016.', '1950-08-26', null, 'Dekina, Northern Region, British Nigeria (now in Kogi State, Nigeria)', 'KO', 'male', 'Peoples Democratic Party', null, 'Politician', '[{"title": "Governor of Kogi State", "term": "27 January 2012 – 27 January 2016"}]', 'wikipedia:person:Idris_Wada'),
('ifeanyi-ararume', 'Ifeanyi Ararume', 'Ifeanyi_Ararume', 'Ifeanyi Godwin Ararume is a Nigerian politician who was appointed as the country''s minister of Petroleum Resources and as the Chairman, Board of Management of the Nigerian National Petroleum Company Limited (NNPC Ltd.), in the wake of implementation of the Petroleum Industry Act (PIA). He was the senator who represented Imo North at the 9th Nigerian National Assembly. He was elected Senator for the Imo North (Okigwe) constituency of Imo State, Nigeria at the start of the Nigerian Fourth Republic, running on the People''s Democratic Party (PDP) platform. He took office on 29 May 1999. He was re-elected in April 2003.', '1958-12-16', null, 'Imo State, Nigeria', 'IM', 'male', 'APC', null, null, '[{"title": "Senator for Imo North", "term": "May 1999 – May 2007"}, {"title": "Senator for Imo North", "term": "Dec 2020 – 2023"}]', 'wikipedia:person:Ifeanyi_Ararume'),
('ifeanyi-odii', 'Ifeanyi Odii', 'Ifeanyi_Odii', 'Ifeanyi Chukwuma Odii is a Nigerian businessman, philanthropist and politician. He is the founder and chairman of Orient Global Group. and also the gubernatorial candidate of the People’s Democratic Party for Ebonyi State in the 2023 gubernatorial election. Odii is a native of Isu in Onicha local government area (LGA) of Ebonyi state, Nigeria.', '1975-04-17', null, 'Onicha, Ebonyi State, Nigeria', 'EB', 'male', null, 'National Open University of Nigeria', 'Businessman, Philanthropist, Politician', '[]', 'wikipedia:person:Ifeanyi_Odii'),
('ifeanyi-okowa', 'Ifeanyi Okowa', 'Ifeanyi_Okowa', 'Ifeanyichukwu Arthur Okowa CON is a Nigerian doctor and politician who served as Governor of Delta State from May 2015 to May 2023. He was a member of the People''s Democratic Party, he was the party''s vice presidential candidate in the 2023 presidential election running alongside Atiku Abubakar who was the presidential candidate.', '1959-07-08', null, 'Owa-Alero, Eastern Region, British Nigeria (now Owa-Alero, Delta State, Nigeria)', 'DE', 'male', 'All Progressive Congress', 'University of Ibadan', 'Politician, medical doctor', '[{"title": "Governor of Delta State", "term": "29 May 2015 – 29 May 2023"}, {"title": "Senator for Delta North", "term": "29 May 2011 – 29 May 2015"}]', 'wikipedia:person:Ifeanyi_Okowa'),
('ifeanyi-ubah', 'Ifeanyi Ubah', 'Ifeanyi_Ubah', 'Patrick Ifeanyi Ubah was a Nigerian politician and businessman who served as the senator representing Anambra South senatorial district from 2019 until his death on 26 July 2024. He was the CEO of Capital Oil (CCO), which he founded in 2001.', '1971-09-03', '2024-07-26', 'Abuja, Nigeria', 'FC', 'male', 'Labour Party', null, 'Politician; businessman', '[{"title": "Senator for Anambra South", "term": "11 June 2019 – 26 July 2024"}]', 'wikipedia:person:Ifeanyi_Ubah'),
('ifeanyi-ugwuanyi', 'Ifeanyi Ugwuanyi', 'Ifeanyi_Ugwuanyi', 'Lawrence Ifeanyi Ugwuanyi CON is a Nigerian politician who served as the governor of Enugu State from 2015 to 2023. He was a member of the House of Representatives of Nigeria representing Igboeze North/Udenu federal constinuency from 2003 to 2015. He is a member of Peoples Democratic Party (PDP).', '1964-03-20', null, 'Orba Town, Eastern Region, Nigeria (now in Enugu State)', 'EN', 'male', 'Peoples Democratic Party', 'University of Nigeria', 'Politician', '[{"title": "5th Governor of Enugu State", "term": "29 May 2015 – 29 May 2023"}, {"title": "Member of the House of Representatives of Nigeria from Enugu", "term": "3 June 2003 – 29 May 2015"}]', 'wikipedia:person:Ifeanyi_Ugwuanyi'),
('ikedi-ohakim', 'Ikedi Ohakim', 'Ikedi_Ohakim', 'Ikedi Ohakim is a Nigerian businessman who became governor of Imo State in the South Eastern region in May 2007, standing for the Progressive Peoples Alliance (PPA). He later switched to the People''s Democratic Party (PDP).', '1957-08-04', null, 'Okohia, Isiala Mbano LGA, Imo State, Nigeria', 'IM', 'male', 'People''s Democratic Party', null, null, '[{"title": "4th Governor of Imo State", "term": "29 May 2007 – May 2011"}]', 'wikipedia:person:Ikedi_Ohakim'),
('isa-ashiru-kudan', 'Isa Ashiru Kudan', 'Isa_Ashiru_Kudan', 'Isa Ashiru Kudan is a Nigerian politician from Kudan, Nigeria. He is a business man and holds the traditional title of Sarkin Bai of Zazzau Emirate. He is the governorship candidate of Peoples Democratic Party for 2023 in Kaduna State, Nigeria. He was previously the House of Representatives of Nigeria representing Kudan/Makarfi Federal Constituency from 2007 to 2015, and Member representing Kudan Constituency at Kaduna State House of Assembly.', '1962-10-23', null, 'Kudan, Kaduna State - Nigeria', 'KD', 'male', 'People Democratic Party', 'Kufena College Wusasa', null, '[{"title": "Member of the House of Representatives of Nigeria", "term": "2007–2015"}, {"title": "Member of Kaduna State House of Assembly", "term": "1999–2007"}]', 'wikipedia:person:Isa_Ashiru_Kudan'),
('isa-yuguda', 'Isa Yuguda', 'Isa_Yuguda', 'Mallam Isa Yuguda is a Nigerian former politician who was the Governor of Bauchi State, Nigeria. He was first elected in April 2007, on the All Nigeria Peoples Party (ANPP) platform. In April 2009, he changed allegiance from the ANPP to the People''s Democratic Party (PDP). Yaguda was reelected governor on 28 April 2011.', '1956-06-15', null, 'Yuguda, Bauchi State, Nigeria', 'BA', 'male', 'APC', null, null, '[{"title": "Federal Minister of Aviation", "term": "May 2003 – June 2005"}, {"title": "Governor of Bauchi State", "term": "29 May 2007 – 29 May 2015"}]', 'wikipedia:person:Isa_Yuguda'),
('issa-aremu', 'Issa Aremu', 'Issa_Aremu', 'Issa Obalowu Aremu is a Nigerian trade union activist and labor leader. He is the general secretary of the National Union of Textile, Garment and Tailoring Workers of Nigeria (NVTGTWN) and vice president of the IndustriALL Global Union. Comrade Issa Aremu is a member of the executive council of the Nigerian Labour Congress, and served as the vice president of the congress during the tenure of Adams Oshiomole.', null, null, null, null, 'male', null, 'University of Port Harcourt', 'Trade Union Activist', '[]', 'wikipedia:person:Issa_Aremu'),
('iyiola-omisore', 'Iyiola Omisore', 'Iyiola_Omisore', 'Iyiola Ajani Omisore is a Nigerian businessman, engineer, and politician who served as deputy governor of Osun State from 1999 to 2003. Subsequently, he served as a member of the Nigerian Senate for Osun East from 2003 to 2011. He is a former national secretary of the All Progressives Congress.', '1957-09-15', null, 'Ile-Ife, Western Region, British Nigeria (now in Osun State, Nigeria)', 'OS', 'male', 'All Progressives Congress', 'SS Peter and Paul Roman Catholic School; St. John Grammar School', 'Politician; engineer; businessman', '[{"title": "National Secretary of the All Progressives Congress", "term": "March 2022 – 17 July 2023"}, {"title": "Senator for Osun East", "term": "3 June 2003 – 6 June 2011"}, {"title": "Deputy Governor of Osun State", "term": "29 May 1999 – 29 May 2003"}]', 'wikipedia:person:Iyiola_Omisore'),
('james-ibori', 'James Ibori', 'James_Ibori', 'James Onanefe Ibori is a Nigerian politician who was Governor of Delta State in Nigeria from 29 May 1999 to 29 May 2007. An ethnic Urhobo by descent, Ibori is a member of the people’s Democratic Party(PDP). He is a leader in the Niger Delta region and a national figure in Nigeria. In 2012, Ibori was sentenced to 13 years in prison for money laundering.', '1959-08-04', null, 'Oghara, Delta State, Nigeria', 'DE', 'male', null, 'University of Benin, Nigeria', null, '[{"title": "2nd Governor of Delta State", "term": "29 May 1999 – 29 May 2007"}]', 'wikipedia:person:James_Ibori'),
('jeremiah-useni', 'Jeremiah Useni', 'Jeremiah_Useni', 'Jeremiah Timbut Useni was a Nigerian army lieutenant general, who served as minister responsible for the administration of the Federal Capital Territory, Abuja under the Sani Abacha military junta. He served Nigeria in various capacities such as Minister for Transport and Quarter-Master General of the Nigeria Army. Useni also served as Deputy Chairman of one of the significant parties in Nigeria, the All Nigeria Peoples Party. He was elected Senator for the Plateau South constituency of Plateau State, Nigeria in the March 2015 national elections. Useni was running on the People''s Democratic Party (PDP) platform.', '1943-02-16', '2025-01-23', 'Langtang, Northern Region, Colony and Protectorate of Nigeria (now in Plateau State, Nigeria)', 'PL', 'male', 'Peoples Democratic Party', null, null, '[{"title": "Senator of the Federal Republic of Nigeria", "term": "May 2015 – June 2019"}, {"title": "Minister of the Federal Capital Territory", "term": "1993–1998"}, {"title": "Governor of Bendel State", "term": "January 1984 – August 1985"}]', 'wikipedia:person:Jeremiah_Useni'),
('jimi-agbaje', 'Jimi Agbaje', 'Jimi_Agbaje', 'Olujimi Kolawole Agbaje, popularly known as Jimi Agbaje, is a Nigerian pharmacist and politician who was a candidate for the governorship of Lagos State in 2007, 2015, and 2019.', '1957-03-02', null, 'Lagos, Lagos State, Nigeria', 'LA', 'male', 'Peoples Democratic Party', 'St Gregory''s College, Lagos; University of Ife (now Obafemi Awolowo University)', 'Pharmacist, Politician', '[]', 'wikipedia:person:Jimi_Agbaje'),
('john-james-akpan-udo-edehe', 'John James Akpan Udo-Edehe', 'John_James_Akpan_Udo-Edehe', 'John James Akpan Udo-Edehe is a Nigerian politician who served as a senator for the Akwa Ibom North East Senatorial District at the start of the Fourth Republic, on the platform of the Peoples Democratic Party (PDP). He took office on 29 May 1999.', '1963-11-09', null, 'Akwa Ibom State, Nigeria', 'AK', 'male', 'Peoples Democratic Party', null, null, '[{"title": "Senator of the Federal Republic of Nigeria from Akwa Ibom North-East Senatorial District", "term": "29 May 1999 – 29 May 2003"}, {"title": "Minister of State for Federal Capital Territory FCT", "term": "26 July 2007 – 29 October 2008"}]', 'wikipedia:person:John_James_Akpan_Udo-Edehe'),
('john-owan-enoh', 'John Owan Enoh', 'John_Owan_Enoh', 'John Owan Enoh is a Nigerian politician, teacher, farmer, and philanthropist. He was the 36th Minister of Sports Development of Nigeria.He is currently the Minister of State for Industry, Federal Ministry of Industry, Trade and Investment (Industry).', '1966-06-04', null, 'Agbokim, Eastern Region (now in Cross River State), Nigeria', 'CR', 'male', 'All Progressives Congress', 'University of Calabar', 'Politician; teacher; farmer', '[{"title": "Honourable Minister of state for Industry.Federal Ministry of Industry, Trade and Investment.", "term": "Since 21 August 2023"}, {"title": "Senator for Cross River Central", "term": "9 June 2015 – 9 June 2019"}, {"title": "Member of the House of Representatives of Nigeria from Cross River", "term": "3 June 2003 – 6 June 2015"}]', 'wikipedia:person:John_Owan_Enoh'),
('jolly-nyame', 'Jolly Nyame', 'Jolly_Nyame', 'Jolly Tavoro Nyame is a Nigerian politician who served as the governor of Taraba State from 1999 to 2007. He previously served as governor from 1992 to 1993 during the short lived third republic.', '1955-12-25', null, 'Zing, Northern Region, British Nigeria (now in Taraba State, Nigeria)', 'TA', 'male', 'All Progressives Congress', 'Bachelor''s Degree in Theology, Emory University, U.S.', 'Politician', '[{"title": "Governor of Taraba State", "term": "29 May 1999 – 29 May 2007"}]', 'wikipedia:person:Jolly_Nyame'),
('jonah-david-jang', 'Jonah David Jang', 'Jonah_David_Jang', 'Jonah David Jang CON is a former Nigerian military officer and politician who served as the senator representing the Plateau North senatorial district from 2015 to 2019. He previously served as the governor of Plateau State from 2007 to 2015, and as military governor of Benue and Gongola States.', '1944-03-13', null, 'Du, Northern Region, British Nigeria (now in Plateau State, Nigeria)', 'PL', 'male', 'Peoples Democratic Party', 'Nigerian Defence Academy', 'Politician; military officer', '[{"title": "Senator for Plateau North", "term": "9 June 2015 – 9 June 2019"}, {"title": "Chairman of the Nigeria Governors'' Forum", "term": "25 May 2013 – 29 May 2015"}, {"title": "Governor of Plateau State", "term": "29 May 2007 – 29 May 2015"}, {"title": "Military Governor of Gongola State", "term": "August 1986 – December 1987"}, {"title": "Military Governor of Benue State", "term": "August 1985 – August 1986"}]', 'wikipedia:person:Jonah_David_Jang'),
('jonathan-asake', 'Jonathan Asake', 'Jonathan_Asake', 'Jonathan Asake is a Nigerian politician and former lawmaker. He was a candidate in the 2023 Kaduna State gubernatorial election under the Labour Party. Prior to his nomination as gubernatorial candidate, he served as the President of Southern Kaduna People''s Union (SOKAPU)', null, null, null, null, 'male', 'Labour Party', null, 'politician', '[]', 'wikipedia:person:Jonathan_Asake'),
('joshua-dariye', 'Joshua Dariye', 'Joshua_Dariye', 'Joshua Chibi Dariye is a Nigerian politician who served as the senator representing the Plateau Central senatorial district from 2011 to 2019. He previously served as the governor of Plateau State from 1999 to 2006 when he was impeached. He was later re-instated by the Supreme Court of Nigeria in the same year and he continued his tenure until May 2007.', '1957-07-27', null, 'Bokkos, Northern Region, British Nigeria (now in Plateau State, Nigeria)', 'PL', 'male', 'All Progressives Congress', null, 'Politician; accountant', '[{"title": "Senator for Plateau Central", "term": "6 June 2011 – 9 June 2019"}, {"title": "Governor of Plateau State", "term": "27 April 2007 – 29 May 2007"}]', 'wikipedia:person:Joshua_Dariye'),
('julius-ucha', 'Julius Ucha', 'Julius_Ucha', 'Julius Ucha was elected Senator for the Ebonyi Central constituency of Ebonyi State, Nigeria, taking office on 29 May 2003, and was reelected in 2007. He is a member of the All Progressives Congress(APC).', '1958-10-19', null, 'Ebonyi State, Nigeria', 'EB', 'male', 'All progressives Congress', null, null, '[{"title": "Senator for Ebonyi Central", "term": "29 May 2003 – May 2011"}]', 'wikipedia:person:Julius_Ucha'),
('kashim-ibrahim-imam', 'Kashim Ibrahim-Imam', 'Kashim_Ibrahim-Imam', 'Kashim Ibrahim-Imam was born 8 May 1962, he is a Nigerian politician who was twice the People''s Democratic Party (PDP) candidate for Governor of Borno State in 2003 and 2007, losing both times to the All Nigeria Peoples Party (ANPP) candidate Ali Modu Sheriff.', null, null, null, null, 'male', null, null, null, '[]', 'wikipedia:person:Kashim_Ibrahim-Imam'),
('kashim-shettima', 'Kashim Shettima', 'Kashim_Shettima', 'Kashim Shettima Mustapha GCON is a Nigerian politician who is the 15th and current vice president of Nigeria. He previously served as senator for Borno Central from 2019 to 2023, and as the governor of Borno State from 2011 to 2019.', '1966-09-02', null, 'Maiduguri, Northern Region, Nigeria (now in Borno State)', 'BO', 'male', 'APC', 'University of Maiduguri; University of Ibadan', 'Politician; banker', '[{"title": "15th Vice President of Nigeria", "term": "Since 29 May 2023"}, {"title": "Senator for Borno Central", "term": "11 June 2019 – 29 May 2023"}, {"title": "Governor of Borno State", "term": "29 May 2011 – 29 May 2019"}]', 'wikipedia:person:Kashim_Shettima'),
('kayode-fayemi', 'Kayode Fayemi', 'Kayode_Fayemi', 'John Olukayode Fayemi CON is a Nigerian politician who served as governor of Ekiti State from 2018 to 2022. He previously served in office between 2010 and 2014 before losing re-election to Ayodele Fayose. He was also the Minister of Solid Minerals Development in President Muhammadu Buhari ''s cabinet from 11 November 2015 to 30 May 2018, when he resigned to contest for a second term as Governor of Ekiti State. He is the pioneer president of the Forum of Regions of Africa (FORAF) since 9 September 2022.', '1965-02-09', null, 'Ibadan, Western Region (now in Oyo State), Nigeria', 'OY', 'male', 'All Progressives Congress', 'Doctorate in War Studies', 'Politician', '[{"title": "Governor of Ekiti State", "term": "16 October 2018 – 16 October 2022"}, {"title": "Minister of Solid Minerals Development", "term": "11 November 2015 – 30 May 2018"}]', 'wikipedia:person:Kayode_Fayemi'),
('kolapo-olushola', 'Kolapo Olushola', 'Kolapo_Olushola', 'Kolapo Olubunmi Olushola Eleka is a Nigerian academic, professor of building technology and politician who served as the deputy governor of Ekiti State from 2014 to 2018.', null, null, null, null, 'male', 'Peoples Democratic Party', 'Obafemi Awolowo University; University of Lagos', 'Politician; academic', '[{"title": "Deputy Governor of Ekiti State", "term": "16 October 2014 – 16 October 2018"}]', 'wikipedia:person:Kolapo_Olushola'),
('labaran-maku', 'Labaran Maku', 'Labaran_Maku', 'Labaran Maku is a Nigerian politician who served as Minister of Information from 2010 to 2015 and as deputy governor of Nasarawa State from 2003 to 2007.', '1962-01-01', null, 'Wakama, Nasarawa State, Nigeria', 'NA', 'male', 'All Progressives Grand Alliance', null, null, '[{"title": "Minister of Information", "term": "December 2010 – January 2015"}, {"title": "Deputy Governor of Nasarawa State", "term": "29 May 2003 – 29 May 2007"}]', 'wikipedia:person:Labaran_Maku'),
('lam-adesina', 'Lam Adesina', 'Lam_Adesina', 'Lamidi Ona-Olapo Adesina CON was a Nigerian educator and politician who served as the governor of Oyo State from 1999 to 2003, as a member of the Alliance for Democracy (AD) party.', null, '2012-11-11', 'Ibadan, Southern Region, British Nigeria (now in Oyo State, Nigeria)', 'OY', 'male', 'Unity Party of Nigeria', 'Loyola College, Ibadan; University of Nigeria; University of Ibadan', 'Politician; educator', '[{"title": "Governor of Oyo State", "term": "29 May 1999 – 29 May 2003"}]', 'wikipedia:person:Lam_Adesina'),
('linus-okorie', 'Linus Okorie', 'Linus_Okorie', 'Linus Chinedu Okorie MFR is a Nigerian leadership consultant, author, and founder of Guardians of the Nation International (GOTNI), a nonprofit leadership development organization which has trained and nurtured elected officials and the general public on effective leadership for the last 25 years. In 2022, he received the Nigerian national honor of Member of the Order of the Federal Republic (MFR) and 2019 Imo State Gubernatorial candidate under the Young Progressives Party.', null, null, null, null, 'male', null, 'Imo State University', 'Leadership expert, Entrepreneur', '[]', 'wikipedia:person:Linus_Okorie'),
('liyel-imoke', 'Liyel Imoke', 'Liyel_Imoke', 'Liyel Imoke CON is a Nigerian politician who served as the governor of Cross River State, Nigeria from 29 May 2007 till 29 May 2015. He is a member of the African Democratic Congress (ADC).', '1961-07-10', null, null, null, 'male', null, null, null, '[{"title": "Senator", "term": "1992–1993"}, {"title": "Federal Minister of Power and Steel", "term": "July 2003 – January 2007"}, {"title": "Governor of Cross River State", "term": "29 May 2007 – May 2015"}]', 'wikipedia:person:Liyel_Imoke'),
('lucky-aiyedatiwa', 'Lucky Aiyedatiwa', 'Lucky_Aiyedatiwa', 'Lucky Orimisan Aiyedatiwa is a Nigerian businessman and politician who has served as governor of Ondo State since 2023. He previously served as deputy governor of Ondo State from 2021 to 2023 under Governor Rotimi Akeredolu. He is a former commissioner of Niger Delta Development Commission.', '1965-01-12', null, 'Ilaje, Western Region (now in Ondo State), Nigeria', 'ON', 'male', 'All Progressive Congress', 'Ikosi High School', 'Politician; businessman', '[{"title": "Governor of Ondo State", "term": "Since 27 December 2023 Acting: 13 December 2023 – 27 December 2023"}, {"title": "Deputy Governor of Ondo State", "term": "24 February 2021 – 27 December 2023"}]', 'wikipedia:person:Lucky_Aiyedatiwa'),
('lucky-igbinedion', 'Lucky Igbinedion', 'Lucky_Igbinedion', 'Lucky Nosakhare Igbinedion is a Nigerian politician who served as the governor of Edo State from 1999 to 2007.', '1957-05-13', null, null, null, 'male', 'Peoples Democratic Party', 'University of Wyoming; MBA, Jackson State University', 'Politician', '[{"title": "Governor of Edo State", "term": "29 May 1999 – 29 May 2007"}]', 'wikipedia:person:Lucky_Igbinedion'),
('lucky-imasuen', 'Lucky Imasuen', 'Lucky_Imasuen', 'Lucky Imasuen is a Nigerian politician who served as the deputy governor of Edo State from 2007 to 2008 under the governorship of Oserheimen Osunbor. Prior to this, Imasuen ran unsuccessfully for the office of the governor of Edo State in 1999 and withdrew his candidacy in the 2024 governorship elections in Edo State.', null, null, null, null, 'male', 'People''s Democratic Party', null, 'Politician', '[{"title": "Deputy Governor of Edo State", "term": "29 May 2007 – 11 November 2008"}]', 'wikipedia:person:Lucky_Imasuen'),
('magaji-abdullahi', 'Magaji Abdullahi', 'Magaji_Abdullahi', 'Engineer Magaji Abdullahi pronunciation was a Nigerian politician. He was the deputy governor of Kano State between 2003 and 2007. Abdullahi led the Water Resources Engineering and Construction Agency (WRECA) in Kano State, Permanent Secretary Ministry of Works and Housing, Director General Ministry of Works, Housing and Transport, Commissioner Ministry of Works, Housing and Transport.', '1947-11-22', '2016-07-24', 'Kano State, Nigeria', 'KN', 'male', 'NCPN', 'Ahmadu Bello University', 'Civil servant', '[{"title": "Deputy Governor", "term": "29 May 2003 – 29 May 2007"}, {"title": "NCPN National Party Chairman", "term": "1995-1998"}]', 'wikipedia:person:Magaji_Abdullahi'),
('mahmud-shinkafi', 'Mahmud Shinkafi', 'Mahmud_Shinkafi', 'Alhaji Mamud Aliyu Shinkafi is a Nigerian politician. He was elected governor of Zamfara State in 2007 on the All Nigeria Peoples Party (ANPP) slate.', null, null, null, null, 'male', null, null, null, '[]', 'wikipedia:person:Mahmud_Shinkafi'),
('mai-mala-buni', 'Mai Mala Buni', 'Mai_Mala_Buni', 'Mai Mala Buni CON is a Nigerian politician who has been serving as the governor of Yobe State since 2019. He was elected as governor during the 2019 Nigeria general elections under the platform of the All Progressives Congress. Prior to his election as governor, he held the position of national secretary of the All Progressives Congress.', '1967-11-19', null, 'Gujba, North-Eastern State (now in Yobe State), Nigeria', 'YO', 'male', 'All Progressive Congress', 'Espam Formation University; Leeds Beckett University', 'Politician', '[{"title": "Governor of Yobe State", "term": "Since 29 May 2019"}, {"title": "Caretaker Chairman of the All Progressives Congress", "term": "25 June 2020 – 22 March 2022"}, {"title": "National Secretary of the All Progressives Congress", "term": "14 June 2014 – March 2019"}]', 'wikipedia:person:Mai_Mala_Buni'),
('mamman-bello-ali', 'Mamman Bello Ali', 'Mamman_Bello_Ali', 'Mamman Bello Ali was a Nigerian politician who served as the governor of Yobe State from 2007 until his death in Florida USA 2009. He previously served as the senator representing the Yobe South senatorial district from 1999 to 2007. He was the chairman senate committee on public account from 1999 to 2007. He was a member of the All Nigeria Peoples Party (ANPP).', '1958', '2009-01-26', null, null, 'male', 'All Nigeria Peoples Party', null, null, '[{"title": "Governor of Yobe State", "term": "29 May 2007 – 26 January 2009"}, {"title": "Senator for Yobe South", "term": "3 June 1999 – 5 June 2007"}]', 'wikipedia:person:Mamman_Bello_Ali'),
('martin-elechi', 'Martin Elechi', 'Martin_Elechi', 'Martin Nwancho Elechi is a Nigerian politician. He served as the governor of Ebonyi State from 2007 to 2015.', null, null, 'Ikwo', null, 'male', 'All Progressives Congress', null, null, '[{"title": "Governor of Ebonyi State", "term": "29 May 2007 – 29 May 2015"}]', 'wikipedia:person:Martin_Elechi'),
('mohammed-abdullahi-abubakar', 'Mohammed Abdullahi Abubakar', 'Mohammed_Abdullahi_Abubakar', 'Mohammed Abdullahi Abubakar is a Nigerian politician who served as governor of Bauchi State from 2015 to 2019.', '1956-12-11', null, 'Gombe, Colonial Nigeria', 'GO', 'male', 'All Progressives Congress', 'Ahmadu Bello University', 'Politician', '[{"title": "Governor of Bauchi State", "term": "29 May 2015 – 29 May 2019"}]', 'wikipedia:person:Mohammed_Abdullahi_Abubakar'),
('mohammed-alkali', 'Mohammed Alkali', 'Mohammed_Alkali', 'Senator Mohammed D. Alkali was elected Senator for the Jigawa North West constituency of Jigawa State, Nigeria at the start of the Nigerian Fourth Republic, running on the People''s Democratic Party (PDP) platform. He served from 29 May 1999 until May 2003.', '1950-01-17', null, 'Gumel LGA, Jigawa State, Nigeria', 'JI', 'male', 'People''s Democratic Party', null, null, '[{"title": "Senator of the Federal Republic of Nigeria from Jigawa State North West District", "term": "May 1999 – May 2003"}]', 'wikipedia:person:Mohammed_Alkali'),
('mohammed-badaru-abubakar', 'Mohammed Badaru Abubakar', 'Mohammed_Badaru_Abubakar', 'Mohammed Badaru Abubakar MON is a Nigerian politician who served as the Nigerian minister of defence from 21 August 2023 to 1 December 2025. He previously served as the governor of Jigawa State from 2015 to 2023.', '1962-09-29', null, 'Babura, Northern Region (now in Jigawa State), Nigeria', 'JI', 'male', 'All Progressives Congress', null, 'Politician', '[{"title": "Minister of Defence", "term": "21 August 2023 – 1 December 2025"}, {"title": "Governor of Jigawa State", "term": "29 May 2015 – 29 May 2023"}]', 'wikipedia:person:Mohammed_Badaru_Abubakar'),
('mohammed-danjuma-goje', 'Mohammed Danjuma Goje', 'Mohammed_Danjuma_Goje', 'Mohammed Danjuma Goje was a former Governor of Gombe State, Nigeria under the platform of the People''s Democratic Party (PDP), taking office on 29 May 2003 during the 2003 Gombe State gubernatorial election. He is now a member of the All Progressives Congress (APC).', '1952-10-10', null, 'Pindiga Town, Akko, Gombe State, Nigeria', 'GO', 'male', 'All Progressive Congress', 'Ahmadu Bello University, Zaria', null, '[{"title": "Minister Of State, Power & Steel", "term": "1999–2001"}, {"title": "Executive Governor of Gombe State", "term": "May 2003 – May 2011"}, {"title": "Senator Representing Gombe Central", "term": "Since May 2011"}]', 'wikipedia:person:Mohammed_Danjuma_Goje'),
('mohammed-goni', 'Mohammed Goni', 'Mohammed_Goni', 'Alhaji Mohammed Goni was a civil servant who was Governor of Borno State, Nigeria in the Nigerian Second Republic.', '1942', '2020-04-30', 'Kareto, Mobbar LGA, Borno State, Nigeria', 'BO', 'male', null, null, null, '[{"title": "Governor of Borno State", "term": "October 1979 – October 1983"}]', 'wikipedia:person:Mohammed_Goni'),
('mohammed-kaliel', 'Mohammed Kaliel', 'Mohammed_Kaliel', 'Mohammed Bello Kaliel (died 10 March 2015) was a Nigerian Army Colonel and the first Governor of Bauchi State, Nigeria after it was created on 3 February 1976 when North-Eastern State was divided into Bauchi, Borno, and Gongola states, during the military regime of General Olusegun Obasanjo. He held office until July 1978.', '1944-06-17', '2015-03-10', 'Kebbi State, Nigeria', 'KE', 'male', null, null, null, '[{"title": "Federal Minister of Water Resources", "term": "1999 – 13 June 2001"}, {"title": "Commander of the Brigade of Guards", "term": "1981–1984"}, {"title": "Governor of Bauchi State", "term": "March 1976 – July 1978"}]', 'wikipedia:person:Mohammed_Kaliel'),
('mohammed-lawal', 'Mohammed Lawal', 'Mohammed_Lawal', 'Mohammed Alabi Lawal Yoruba pronunciation; January 24, 1946 – November 15, 2006) was a Nigerian naval officer who was military governor of Ogun State between December 1987 and August 1990 during the military administration of General Ibrahim Babangida. He was one of the pioneers of the Nigeria Navy Secondary School Abeokuta.The then Navy Captain Mohammed Lawal, invited the Nigerian Navy to consider a location of the defunct St Leo''s Teachers'' Training College at Ibara Abeokuta (www.nnssab.net)on a hilly Onikolobo site. This premises had been abandoned and merely served as a route to the Catholic Compound and was also used for administering a newly conceived secondary school in that name.', null, '2006-11-15', 'Ilorin', null, 'male', null, null, null, '[{"title": "Governor of Kwara State", "term": "29 May 1999 – 29 May 2003"}, {"title": "Military Governor of Ogun State", "term": "December 1987 – August 1990"}]', 'wikipedia:person:Mohammed_Lawal'),
('mohammed-umar-bago', 'Mohammed Umar Bago', 'Mohammed_Umar_Bago', 'Mohammed Umar is a Nigerian banker, farmer and politician who is the current governor of Niger State since 29 May 2023.', '1974-02-22', null, 'Minna, North-Central State (now in Niger State), Nigeria', 'NI', 'male', 'All Progressives Congress', null, 'Politician; Bankerl Farmer', '[{"title": "Governor of Niger State", "term": "Since 29 May 2023"}, {"title": "Member of the House of Representatives of Nigeria from Niger", "term": "6 June 2011 – 29 May 2023"}]', 'wikipedia:person:Mohammed_Umar_Bago'),
('monday-okpebholo', 'Monday Okpebholo', 'Monday_Okpebholo', 'Monday Okpebholo is a Nigerian businessman and politician who has been the governor of Edo State since 12 November 2024. He was the senator representing Edo Central senatorial district from 2023 to 2024.', null, null, null, null, 'male', 'All Progressive Congress', 'University of Abuja (BBA)', 'Politician; businessman', '[{"title": "Governor of Edo State", "term": "Since 12 November 2024"}, {"title": "Senator for Edo Central", "term": "13 June 2023 – 12 November 2024"}]', 'wikipedia:person:Monday_Okpebholo'),
('muhammad-inuwa-yahaya', 'Muhammad Inuwa Yahaya', 'Muhammad_Inuwa_Yahaya', 'Muhammad Inuwa Yahaya is a Nigerian businessman and politician who has served as the governor of Gombe State since 2019.', '1961-10-09', null, 'Jekadefari, Northern Region, Nigeria (now in Gombe State)', 'GO', 'male', 'All Progressive Congress', 'Ahmadu Bello University', 'Politician; businessman', '[{"title": "Governor of Gombe State", "term": "Since 29 May 2019"}]', 'wikipedia:person:Muhammad_Inuwa_Yahaya'),
('muhammadu-buhari', 'Muhammadu Buhari', 'Muhammadu_Buhari', 'Muhammadu Buhari was a Nigerian general and politician who ruled as military dictator of Nigeria from 1983 to 1985, and later served as the democratically elected civilian president of Nigeria from 2015 to 2023.', '1942-12-17', '2025-07-13', 'Daura, Northern Region, British Nigeria', null, 'male', 'All Progressives Congress', 'Nigerian Military Training College; Mons Officer Cadet School; U.S. Army War College', 'Politician; military officer', '[{"title": "7th & 15th President of Nigeria", "term": "29 May 2015 – 29 May 2023"}, {"title": "Federal Minister of Petroleum Resources", "term": "11 November 2015 – 29 May 2023"}, {"title": "Governor of Borno State", "term": "3 February 1976 – 15 March 1976"}]', 'wikipedia:person:Muhammadu_Buhari'),
('mukhtar-shehu-idris', 'Mukhtar Shehu Idris', 'Mukhtar_Shehu_Idris', 'Mukhtar Shehu Idris is a Nigerian administrator and politician. He was the governor-elect of Zamfara State in the 2019 gubernatorial election under the platform of All Progressive Congress (APC). Five days to his inauguration as governor of Zamfara State the Supreme Court annulled the election of Idris and all APC candidates in the 2019 elections and ordered Independent National Electoral Commission to declare all first runners in the election who satisfied the requirements of the law winners of the polls.', '1974-04-04', null, 'Tudun Wada', null, 'male', 'All Progressive Congress', null, 'Administrator, politician', '[]', 'wikipedia:person:Mukhtar_Shehu_Idris'),
('mukhtar-yero', 'Mukhtar Yero', 'Mukhtar_Yero', 'Mukhtar Ramalan Yero is a Nigerian politician who served as the Governor of Kaduna State from 2012 to 2015, following the death of Patrick Yakowa in a helicopter crash. He previously served as Deputy governor from 2010 to 2012 and as Kaduna State Commissioner of Finance from 2007 to May 2010 when Yakowa named him deputy governor after he succeeded Namadi Sambo who became the vice president of Nigeria.', '1968-05-01', null, 'Zaria, North-Central State (now Kaduna State), Nigeria', null, 'male', 'All Progressives Congress', 'Ahmadu Bello University', 'Politician', '[{"title": "Governor of Kaduna State", "term": "16 December 2012 – 29 May 2015"}, {"title": "Deputy Governor of Kaduna State", "term": "May 2010 – 16 December 2012"}, {"title": "Kaduna State Commissioner of Finance", "term": "June 2007 – May 2010"}]', 'wikipedia:person:Mukhtar_Yero'),
('murtala-nyako', 'Murtala Nyako', 'Murtala_Nyako', 'Murtala Hamman-Yero Nyako, GCON CFR is a Nigerian politician and retired military officer who served as governor of Adamawa State from 2007 to 2008, and from 2008 to 2014. He previously served as military governor of Niger State from its creation in 1976 to 1977. He was a former Chief of the Naval Staff from 1990 to 1992.', '1942-08-27', null, 'Mayo-Belwa, British Cameroon (now in Adamawa State, Nigeria)', 'AD', 'male', 'All Progressive Congress', 'Britannia Royal Naval College', 'Politician; military officer', '[{"title": "Governor of Adamawa State", "term": "29 April 2008 – 15 July 2014"}, {"title": "Chief of Naval Staff", "term": "January 1990 – February 1992"}, {"title": "Governor of Niger State", "term": "February 1976 – December 1977"}]', 'wikipedia:person:Murtala_Nyako'),
('musiliu-obanikoro', 'Musiliu Obanikoro', 'Musiliu_Obanikoro', 'Musiliu Babatunde Obanikoro (popularly known as Koro) is a Nigerian politician. He served as Senator for Lagos Central from 2003 to 2007, and was later appointed High Commissioner to Ghana. He briefly served as Minister of State for Defence in 2014.', null, null, 'Lagos', 'LA', 'male', 'All Progressive Congress', 'Texas Southern University', 'Politician', '[{"title": "Senator for Lagos Central", "term": "3 June 2003 – 5 June 2007 Serving with Adeleke Mamora and Tokunbo Afikuyomi"}, {"title": "Minister of State for Defence", "term": "2014 – October 2014"}]', 'wikipedia:person:Musiliu_Obanikoro'),
('mustafa-bello', 'Mustafa Bello', 'Mustafa_Bello', 'Mustafa Bello was appointed Nigerian Minister of Commerce in the first cabinet of President Olusegun Obasanjo, holding office between June 1999 and 2002. He became head of the Nigerian Investment Promotion Commission (NIPC) in December 2003.', '1954-01-31', null, 'Niger State, Nigeria', 'NI', 'male', 'PDP', null, null, '[{"title": "Minister of Commerce", "term": "June 1999 – 2002"}]', 'wikipedia:person:Mustafa_Bello'),
('najeem-salaam', 'Najeem Salaam', 'Najeem_Salaam', 'Najeem Folasayo Salam, popularly called Iwaloye (meaning: proven character is royal), is a Nigerian politician and philanthropist. He is a former speaker of the Osun State House of Assembly. Aside Dr. Najeem Folasayo Salaam''s active presence in progressive fold politics as a grassroot politician, he has several academic publications to his credit. One of such works is the best-selling textbook, Rudiments of Government and Politics, published in 2019 by Concept Publications, Lagos, Nigeria, which he co-authored with Dr. Solomon Ayegba Usman.', null, null, null, null, 'male', null, null, null, '[]', 'wikipedia:person:Najeem_Salaam'),
('namadi-sambo', 'Namadi Sambo', 'Namadi_Sambo', 'Mohammed Namadi Sambo GCON is a Nigerian politician who served as the vice president of Nigeria from 19 May 2010 to 29 May 2015. He previously served as governor of Kaduna State from 2007 to 2010.', '1954-08-02', null, 'Zaria, Northern Region, British Nigeria (now in Kaduna State, Nigeria)', 'KD', 'male', 'Peoples Democratic Party', 'Ahmadu Bello University (B.Sc and M.Sc)', 'Politician; architect', '[{"title": "13th Vice President of Nigeria", "term": "19 May 2010 – 29 May 2015"}, {"title": "Governor of Kaduna State", "term": "29 May 2007 – 19 May 2010"}]', 'wikipedia:person:Namadi_Sambo'),
('nasir-el-rufai', 'Nasir El-Rufai', 'Nasir_El-Rufai', 'Nasir Ahmad el-Rufai CON is a Nigerian politician who served as the governor of Kaduna State from 2015 to 2023. A member of the African Democratic Congress (ADC) since November 2025 after his defection from the All Progressives Congress (APC) which he was one of the founding member, and served as the minister of the Federal Capital Territory from 2003 to 2007 under the presidency of Olusegun Obasanjo.', '1960-02-16', null, 'Daudawa, Northern Region, British Nigeria (present day Katsina State, Nigeria)', 'KT', 'male', 'African Democratic Congress', 'Barewa College; Ahmadu Bello University; Harvard University', null, '[{"title": "Governor of Kaduna State", "term": "29 May 2015 – 29 May 2023"}, {"title": "Minister of the Federal Capital Territory", "term": "17 July 2003 – 27 July 2007"}]', 'wikipedia:person:Nasir_El-Rufai'),
('nasir-idris', 'Nasir Idris', 'Nasir_Idris', 'Mohammed Nasir Idris is a Nigerian unionist, educationist, politician who serves as the current governor of Kebbi State. He previously served as national president of the Nigerian Union of Teachers and deputy president of the Nigeria Labour Congress. On 17 April 2023, Idris was pronounced winner of the 2023 Kebbi State gubernatorial election by Independent National Electoral Commission (INEC).', '1965-08-06', null, 'Birnin Kebbi, Northern Region, Nigeria (now in Kebbi State)', 'KE', 'male', 'All Progressives Congress', null, null, '[{"title": "Governor of Kebbi State", "term": "Since 29 May 2023"}]', 'wikipedia:person:Nasir_Idris'),
('nasir-yusuf-gawuna', 'Nasir Yusuf Gawuna', 'Nasir_Yusuf_Gawuna', 'Nasiru Yusuf Gawuna is a Nigerian health personnel, businessman and politician. In May 2022, he became the Governorship Candidate of the All Progressives Congress for the 2023 Kano State gubernatorial election. He served as deputy governor of Kano State under Governor Abdullahi Umar Ganduje from 2018 to 2023. In 2026, he joined the Nigeria Democratic Congress (NDC) and became the party''s candidate for Kano Central Senatorial District in the 2027 Nigerian general election.', '1967-08-06', null, 'Kano, Kano State, Nigeria', 'KN', 'male', 'African Democratic Congress', 'Gawuna Primary School; Government Secondary School Gwaram; Science Secondary School Dawakin Kudu', 'Politician; businessman', '[{"title": "Chairman Governing Council of Federal Mortgage Bank of Nigeria", "term": "24 January 2025 – 30 March 2026"}, {"title": "Chairman Governing Council of Bayero University Kano", "term": "15 June 2024 – 2025"}, {"title": "Deputy Governor of Kano State", "term": "19 September 2018 – 29 May 2023"}, {"title": "Kano State Commissioner for Agriculture", "term": "2014–2022"}, {"title": "Chairman of Nassarawa LGA", "term": "2007–2014"}]', 'wikipedia:person:Nasir_Yusuf_Gawuna'),
('niyi-adebayo', 'Niyi Adebayo', 'Niyi_Adebayo', 'Otunba Adeniyi Adebayo is a Nigerian lawyer and politician who served as the Minister of Industry, Trade and Investment of Nigeria from August 2019 to May 2023. He previously served as the first democratically elected governor of Ekiti State from 29 May 1999 to 29 May 2003 on the platform of the Alliance for Democracy (AD).', '1958-02-04', null, null, null, 'male', 'All Progressives Congress', 'University of Lagos (LL.B.)', 'Politician; lawyer', '[{"title": "Minister of Industry, Trade and Investment", "term": "21 August 2019 – 29 May 2023"}, {"title": "Governor of Ekiti State", "term": "29 May 1999 – 29 May 2003"}]', 'wikipedia:person:Niyi_Adebayo'),
('nuhu-ribadu', 'Nuhu Ribadu', 'Nuhu_Ribadu', 'Nuhu Ribadu Sardauna adamawa mni is a Nigerian politician, barrister and retired police officer who is currently serving as the National Security Adviser to Nigerian President Bola Tinubu.', null, null, null, null, 'male', null, null, null, '[]', 'wikipedia:person:Nuhu_Ribadu'),
('nyesom-wike', 'Nyesom Wike', 'Nyesom_Wike', 'Ezenwo Nyesom Wike CON is a Nigerian politician and lawyer who has served as the minister of the Federal Capital Territory since 2023. He previously served as the governor of Rivers State from 2015 to 2023. He is also considered a champion of infrastructural development or nicknamed "Mr Project".', '1967-12-13', null, 'Obio-Akpor, Rivers State, Nigeria', 'RI', 'male', 'People''s Democratic Party', 'Master of Arts degree in Political and Administrative Studies', 'Politician; lawyer', '[{"title": "Minister of the Federal Capital Territory", "term": "Since 21 August 2023"}, {"title": "16th Governor of Rivers State", "term": "29 May 2015 – 29 May 2023"}, {"title": "Minister of Education", "term": "11 September 2013 – April 2014"}, {"title": "Minister of State for Education", "term": "14 July 2011 – April 2014"}, {"title": "Chief of Staff to the Governor of Rivers State", "term": "2007–2011"}, {"title": "Chairman of Obio-Akpor Local Government", "term": "1999–2007"}]', 'wikipedia:person:Nyesom_Wike'),
('obadiah-mailafia', 'Obadiah Mailafia', 'Obadiah_Mailafia', 'Obadiah Mailafia was a Nigerian development economist and the 2019 Nigeria Presidential election Candidate of African Democratic Congress (ADC). He was a former official of the African Development Bank Group and one-time Deputy Governor of the Central Bank of Nigeria (CBN). He was also the Chief of Staff of the African, Caribbean and Pacific Group of States (ACP), the 79-nation multilateral development institution based in Brussels, Belgium.', null, '2021-09-19', 'Randa, Nigeria', null, 'male', 'African Democratic Congress', 'Ahmadu Bello University; University of Oxford, Oriel College, DPhil Oxon', null, '[{"title": "Deputy Governor of the Central Bank of Nigeria", "term": "5 May 2005 – 26 March 2007"}]', 'wikipedia:person:Obadiah_Mailafia'),
('ogbonnaya-onu', 'Ogbonnaya Onu', 'Ogbonnaya_Onu', 'Ogbonnaya Onu CON was a Nigerian politician, author and engineer. He was the first civilian governor of Abia State and was the minister of science, technology and innovation of Nigeria from November 2015 until his resignation in 2022. He was the longest serving minister of the ministry.', '1951-12-01', '2024-04-11', 'Ohaozara, Southern Region, Colony and Protectorate of Nigeria (now in Ebonyi State, Nigeria)', 'EB', 'male', 'All Progressives Congress', 'Doctor of Philosophy degree in Chemical Engineering', 'Politician; engineer', '[{"title": "Minister of Science, Technology and Innovation", "term": "14 June 2019 – 11 May 2022"}, {"title": "Governor of Abia State", "term": "January 1992 – November 1993"}]', 'wikipedia:person:Ogbonnaya_Onu'),
('okezie-ikpeazu', 'Okezie Ikpeazu', 'Okezie_Ikpeazu', 'Okezie Victor Ikpeazu is a Nigerian politician and former Governor of Abia State, who was in office from 29 May 2015 to 29 May 2023. He was elected on the platform of the Peoples Democratic Party. He was re-elected as the Governor of Abia state at the 9 March 2019 gubernatorial election. He ran for election at the 2023 Senatorial election for Abia South Senatorial District but came a distant third behind incumbent Senator Enyinnaya Abaribe of All Progressive Grand Alliance and a political newbie Chinedu Onyeizu of the Labour Party.', '1964-10-18', null, 'Abia State, Nigeria', 'AB', 'male', 'People''s Democratic Party', null, null, '[{"title": "Nigeria Ambassador to Spain", "term": "Since 14 September 2026"}, {"title": "9th Governor of Abia State", "term": "29 May 2015 – 29 May 2023"}, {"title": "1st Deputy General Manager of Abia State Environmental Protection Agency", "term": "5 May 2013 – 10 October 2014"}, {"title": "General Manager of the Abia State Passenger Integrated Manifest Scheme ASPIMS", "term": "March 2011 – 5 May 2013"}, {"title": "Chairman of the Governing Council of Abia State College of Health Technology", "term": "June 2010 – 29 May 2011"}, {"title": "General Manager of Abia State Passenger Integrated Manifest Scheme ASPIMS", "term": "2007–2009"}, {"title": "Chairman of Obingwa Local Government Area", "term": "2002–2003"}]', 'wikipedia:person:Okezie_Ikpeazu'),
('oladipupo-olatunde-adebutu', 'Oladipupo Olatunde Adebutu', 'Oladipupo_Olatunde_Adebutu', 'Oladipupo Olatunde Adebutu is a Nigerian politician from Ogun State. In 1992, at the age of 30, he won his seat in the National Assembly, where he represented the Remo Federal Constituency under the umbrella of the now defunct Social Democratic Party (SDP). He ran for Senate under the United National Congress Party (UNCP) in 1998 and the National Assembly in 2003, 2007, and 2011 as a member of the Peoples Democratic Party (PDP).', '1962-02-25', null, 'Lagos, Lagos State, Nigeria', 'LA', 'male', 'People''s Democratic Party', 'Igbobi College, Lagos; University of Lagos', null, '[]', 'wikipedia:person:Oladipupo_Olatunde_Adebutu'),
('olagunsoye-oyinlola', 'Olagunsoye Oyinlola', 'Olagunsoye_Oyinlola', 'Ọlagunsoye Oyinlọla is a retired Nigerian military general, who became governor of Osun State, Nigeria in May 2003, and was reelected in 2007. He was a member of the ruling Peoples Democratic Party (PDP).', '1951-02-03', null, 'Okuku, Southern Region, British Nigeria (now in Osun State, Nigeria)', 'OS', 'male', 'African Democratic Congress', null, null, '[{"title": "Governor of Osun State", "term": "29 May 2003 – 26 November 2010"}, {"title": "Military Governor of Lagos State", "term": "December 1993 – August 1996"}]', 'wikipedia:person:Olagunsoye_Oyinlola'),
('olumide-akpata', 'Olumide Akpata', 'Olumide_Akpata', 'Olumide Osaigbovo Akpata is a Nigerian legal practitioner and politician. He was a senior partner and the head of the Corporate and Commercial Practice Group at Templars law firm in Nigeria until his resignation on 31 August 2023 to enable him to pursue partisan politics. In September 2023, he hosted the program "KingsWeek 2023" with the Old Boys Association, King''s College, Lagos. He became the first non-Senior Advocate of Nigeria in 28 years to be elected president of the Nigerian Bar Association in July 2020.', '1972-10-07', null, 'Edo State, Nigeria', 'ED', 'male', 'Labour Party', null, null, '[{"title": "President of the Nigerian Bar Association", "term": "28 August 2020 – 19 July 2022"}]', 'wikipedia:person:Olumide_Akpata'),
('olusegun-agagu', 'Olusegun Agagu', 'Olusegun_Agagu', 'Olusegun Kokumo Agagu was a Nigerian politician who was a governor of Ondo State from 29 May 2003 until February 2009, when a court voided his re-election as governor on account of electoral irregularities. He was replaced as a governor by Olusegun Mimiko, the runner-up in the election. He was a member of the then-ruling Peoples Democratic Party (PDP).', '1948-02-16', '2013-09-13', 'Okitipupa, Southern Region, British Nigeria (now in Ondo State, Nigeria)', 'ON', 'male', 'Peoples Democratic Party', 'St. Luke''s Anglican School, Okitipupa; Ebenezer African Church School, Ibadan', 'Politician', '[{"title": "Governor of Ondo State", "term": "29 May 2003 – 23 February 2009"}, {"title": "Federal Minister of Power and Steel", "term": "2000–2002"}, {"title": "Federal Minister of Aviation", "term": "29 May 1999 – 2000"}, {"title": "Deputy Governor of Ondo State", "term": "3 January 1992 – 17 November 1993"}]', 'wikipedia:person:Olusegun_Agagu'),
('olusegun-mimiko', 'Olusegun Mimiko', 'Olusegun_Mimiko', 'Olusegun Rahman Mimiko is a Nigerian medical doctor and politician who served as governor of Ondo State from 2009 to 2017. He was the senatorial candidate of the Zenith Labour Party for Ondo Central District in the 2019 Senate elections. He served as the 16th (5th civilian) governor of Ondo State, becoming the first two-term governor of Ondo State, and the first Labour Party governor in Nigeria. Mimiko was previously a federal minister for housing and urban development, a secretary to the Ondo State Government, and a two-time Ondo State Commissioner for Health.', '1954-10-03', null, 'Ondo, Western Region, British Nigeria (now in Ondo State, Nigeria)', 'ON', 'male', 'Peoples Democratic Party', null, 'Politician; Medical doctor', '[{"title": "Governor of Ondo State", "term": "24 February 2009 – 24 February 2017"}, {"title": "Minister of Housing and Urban Development", "term": "July 2005 – 8 December 2006"}, {"title": "Secretary to the Ondo State Government", "term": "2003 – July 2005"}, {"title": "Ondo State Commissioner of Health", "term": "1999 – November 2002"}]', 'wikipedia:person:Olusegun_Mimiko'),
('olusegun-oni', 'Olusegun Oni', 'Olusegun_Oni', 'Olusegun Oni is a Nigerian politician who served as governor of Ekiti State from 29 May 2007 to 17 February 2009 and from 6 May 2009 to 15 October 2010. He was a member of the ruling Peoples Democratic Party (PDP). In 2014 he defected from the PDP and joined the newly formed opposition party All Progressive Congress (APC) where He was given the position of Deputy National Chairman South from 2014 to 2020.', '1954-09-05', null, 'Ifaki, Southern Region, British Nigeria (now in Ekiti State, Nigeria)', 'EK', 'male', 'Social Democratic Party', null, 'Politician', '[{"title": "Deputy National Chairman of All Progressive Congress (South)", "term": "2014–2020"}, {"title": "Governor of Ekiti State", "term": "6 May 2009 – 15 October 2010"}]', 'wikipedia:person:Olusegun_Oni'),
('olusegun-osoba', 'Olusegun Osoba', 'Olusegun_Osoba', 'Chief Olusegun Osoba is a Nigerian journalist and politician who served twice as governor of Ogun State first from 1992 to 1993 during the Nigerian Third Republic and then from 1999 to 2003.', '1939-07-15', null, 'Osogbo, Southern Region, British Nigeria (now in Osun State, Nigeria)', 'OS', 'male', 'Social Democratic Party', 'Methodist Boys'' High School, Lagos; University of Lagos; Indiana University', 'Politician; journalist', '[{"title": "Governor of Ogun State", "term": "29 May 1999 – 29 May 2003"}]', 'wikipedia:person:Olusegun_Osoba'),
('orji-uzor-kalu', 'Orji Uzor Kalu', 'Orji_Uzor_Kalu', 'Orji Uzor Kalu MON is a Nigerian politician and businessman who is the senator representing Abia North Senatorial District. He served as governor of Abia State from 29 May 1999 to 29 May 2007. Kalu is the chairman of SLOK Holding and the Daily Sun and New Telegraph newspapers in Nigeria.', '1960-04-21', null, 'Abia State, Nigeria', 'AB', 'male', 'All Progressives Congress', 'Bachelor of Arts degree', 'Politician; Businessperson', '[{"title": "Senator for Abia North", "term": "Since 11 June 2019"}, {"title": "Senate Majority Whip", "term": "2 July 2019 – 11 June 2023"}, {"title": "7th Governor of Abia State", "term": "29 May 1999 – 29 May 2007"}]', 'wikipedia:person:Orji_Uzor_Kalu'),
('osagie-ize-iyamu', 'Osagie Ize-Iyamu', 'Osagie_Ize-Iyamu', 'Osagie Ize-Iyamu is a Nigerian pastor, politician, and former Chief of Staff and Secretary to the Edo State Government. He was the gubernatorial candidate of the Edo state People''s Democratic Party for the 2016 Edo State gubernatorial election. He is currently a member of the All Progressives Congress (APC). Ize-Iyamu was the National Vice-Chairman, South-South Zone, of the defunct Action Congress of Nigeria (ACN).', '1961-06-21', null, 'Benin City, Edo, Nigeria', 'ED', 'male', 'All Progressives Congress', null, 'Pastor, Politician, Lawyer and Farmer', '[{"title": "Chief of Staff to Edo state government", "term": "1999–2003"}, {"title": "SSG of Edo State", "term": "2003–2007"}]', 'wikipedia:person:Osagie_Ize-Iyamu'),
('osaro-onaiwu', 'Osaro Onaiwu', 'Osaro_Onaiwu', 'Earl Osaro Osaze Onaiwu is a Nigerian politician, entrepreneur, impresario and socialite; he is Director-General of the PDP Governors Forum and former gubernatorial nominee for the All Progressives Grand Alliance of Edo State in the 2016 election. Born in Benin City to parents who were both academics, Onaiwu attended Ogbe Primary School before going to Baptist High School. Onaiwu studied Mass Communication in Auchi Polytechnic, Edo State. Founder of fashion houses Jalomeseki Couture and Osaronno, Africa''s first all white bespoke menswear brand. Founder of Red Carpet Protocol, a reputation management consultancy, established in 2006, serving 36 state governments till date.', null, null, null, null, null, null, null, null, '[]', 'wikipedia:person:Osaro_Onaiwu'),
('oserheimen-osunbor', 'Oserheimen Osunbor', 'Oserheimen_Osunbor', 'Oserheimen Aigberaodion Osunbor is a Nigerian lawyer and politician who served as the governor of Edo State from 2007 to 2008. He served as the senator representing the Edo Central senatorial district from the start of the fourth republic in 1999 to 2007.', '1951-10-05', null, 'Iruekpen, Southern Region, British Nigeria (now in Edo State, Nigeria)', 'ED', 'male', 'All Progressives Congress', 'P.T.T.C Demonstration Primary School, Igueben; Anglican Grammar School, Ujoelen; Holy Trinity Grammar School, Sabongidaa-Ora', 'Politician; lawyer', '[{"title": "Governor of Edo State", "term": "29 May 2007 – 11 November 2008"}, {"title": "Senator from Edo Central", "term": "3 June 1999 – 29 May 2007"}]', 'wikipedia:person:Oserheimen_Osunbor'),
('ovie-omo-agege', 'Ovie Omo-Agege', 'Ovie_Omo-Agege', 'Obarisi Ovie Omo-Agege CFR is a Nigerian lawyer and politician who served as the Deputy President of the Nigerian Senate from 2019 to 2023. He was the senator representing Delta Central Senatorial District from 2015 to 2023.', '1963-08-03', null, 'Orogun, Mid-Western Region, Nigeria (now in Delta State)', 'DE', 'male', 'Nigeria Democratic Congress', 'University of Benin', 'Politician; lawyer', '[{"title": "Deputy President of the Nigerian Senate", "term": "11 June 2019 – 11 June 2023"}, {"title": "Senator for Delta Central", "term": "9 June 2015 – 11 June 2023"}]', 'wikipedia:person:Ovie_Omo-Agege'),
('patrick-yakowa', 'Patrick Yakowa', 'Patrick_Yakowa', 'Patrick Ibrahim Yakowa was a Nigerian politician who served as Governor of Kaduna State from 2010 to 2012. He was appointed deputy governor of Kaduna State in July 2005, following the death of Stephen Shekari and was elected in 2007. He was sworn in as governor on 20 May 2010, replacing governor Namadi Sambo who had been sworn in as vice president the day before. Yakowa successfully ran for election as Kaduna Governor in the 26 April 2011 polls.', null, '2012-12-15', 'Fadan Kagoma, Jema''a, Northern Region, British Nigeria (now in Kaduna State, Nigeria)', 'KD', 'male', 'Peoples Democratic Party', 'Ahmadu Bello University', 'Politician', '[{"title": "Governor of Kaduna State", "term": "20 May 2010 – 15 December 2012"}, {"title": "Deputy Governor of Kaduna State", "term": "21 July 2005 – 20 May 2010"}]', 'wikipedia:person:Patrick_Yakowa'),
('pauline-tallen', 'Pauline Tallen', 'Pauline_Tallen', 'Pauline Tallen OFR is a Nigerian politician who served as the Minister for Women Affairs and Social Development from 2019 to 2023. She was appointed in 2019 by President Muhammadu Buhari after turning down an ambassadorial nomination in 2015 on the grounds that she was not consulted prior to the announcement of the appointment and that she would not accept the offer for equal distribution of power among the three senatorial districts of her native state of plateau because she is from same local government as Governor Simon Lalong.', '1959-01-08', null, 'Shendam, Northern Region, British Nigeria (now in Plateau State, Nigeria)', 'PL', 'female', 'All Progressives Congress', 'University of Jos', 'Politician', '[{"title": "Minister of Women Affairs and Social Development", "term": "21 August 2019 – 29 May 2023"}, {"title": "Deputy Governor of Plateau State", "term": "29 May 2007 – 29 May 2011"}, {"title": "Minister of State for Science and Technology", "term": "1999–2003"}]', 'wikipedia:person:Pauline_Tallen'),
('peter-mbah', 'Peter Mbah', 'Peter_Mbah', 'Peter Ndubuisi Mbah is a Nigerian maritime lawyer, financial analyst, and politician who has served as Governor of Enugu State since 2023. He is the founder and Chief Executive Officer (CEO) of Pinnacle Oil and Gas Ltd.', '1972-03-17', null, 'Enugu, Enugu State, Nigeria', 'EN', 'male', 'All Progressive Congress', 'Lagos State University; Lagos Business School; Nigerian Law School', 'Politician; lawyer; businessman', '[{"title": "6th Governor of Enugu State", "term": "Since 29 May 2023"}]', 'wikipedia:person:Peter_Mbah'),
('peter-obi', 'Peter Obi', 'Peter_Obi', 'Peter Onwubuasi Gregory Obi CON is a Nigerian politician and businessman who served as the governor of Anambra State from 17 March 2006 until his impeachment on 2 November 2006. Reinstated on 9 February 2007, he continued his tenure until 2010, when he was re-elected for a second term, which ended on 7 March 2014. On October 7, 2014, he defected from the All Progressives Grand Alliance (APGA) and joined the Peoples Democratic Party (PDP). On October 13, 2018, former Vice President Atiku Abubakar picked Obi as his running mate ahead of the 2019 presidential election on the PDP platform but lost to late Muhammadu Buhari of the All Progressives Congress (APC).', '1961-07-19', null, 'Onitsha, Anambra State, Nigeria', 'AN', 'male', 'Nigeria Democratic Congress', 'Christ the King College; University of Nigeria', null, '[{"title": "Governor of Anambra State", "term": "14 June 2007 – 17 March 2014"}]', 'wikipedia:person:Peter_Obi'),
('peter-odili', 'Peter Odili', 'Peter_Odili', 'Peter Otunuya Odili is a Nigerian politician who was the third elected Governor of Rivers State in Nigeria from 29 May 1999 to 29 May 2007. Odili is a member of the Peoples Democratic Party (PDP).', '1948-08-15', null, null, null, 'male', 'Peoples Democratic Party', null, 'Politician', '[{"title": "13th Governor of Rivers State", "term": "29 May 1999 – 29 May 2007"}, {"title": "2nd Deputy Governor of Rivers State", "term": "1992–1993"}]', 'wikipedia:person:Peter_Odili'),
('rabiu-kwankwaso', 'Rabiu Kwankwaso', 'Rabiu_Kwankwaso', 'Mohammed Rabi''u Musa Kwankwaso, FNSE FNIQS is a Nigerian politician who served as governor of Kano State from 1999 to 2003 and from 2011 to 2015. After he lost his re-election in 2003, he was appointed the first Minister of Defence of the Fourth Republic with no prior military background, from 2003 to 2007, under administration of President Olusegun Obasanjo. He was later elected to the Senate in 2015, serving one term under the platform of the All Progressives Congress (APC), representing Kano Central Senatorial District.', '1956-10-21', null, 'Kwankwaso, Northern Region, British Nigeria (now in Kano State, Nigeria)', 'KN', 'male', 'Nigeria Democratic Congress', 'Middlesex Polytechnic; Loughborough University of Technology', 'Politician; civil servant; engineer', '[{"title": "Senator for Kano Central", "term": "9 June 2015 – 9 June 2019"}, {"title": "Governor of Kano State", "term": "29 May 2011 – 29 May 2015"}, {"title": "Minister of Defence", "term": "July 2003 – May 2007"}, {"title": "Deputy Speaker of the House of Representatives of Nigeria", "term": "5 December 1992 – 17 November 1993"}, {"title": "Member of the House of Representatives of Nigeria from Kano", "term": "5 December 1992 – 17 November 1993"}]', 'wikipedia:person:Rabiu_Kwankwaso'),
('rauf-aregbesola', 'Rauf Aregbesola', 'Rauf_Aregbesola', 'Ogbeni Rauf Adesoji Aregbesola is a Nigerian politician who served as the minister of the Interior of Nigeria from 2019 to 2023. He previously served as governor of Osun State from 2010 to 2018. He is currently the interim national secretary of the African Democratic Congress (ADC) after his defection from the APC to the party in 2025.', '1957-05-25', null, 'Ilesa, Western Region, British Nigeria (now in Osun State, Nigeria)', 'OS', 'male', 'African Democratic Congress', 'The Polytechnic, Ibadan', 'Politician; engineering technologist', '[{"title": "Minister of the Interior", "term": "21 August 2019 – 29 May 2023"}, {"title": "Governor of Osun State", "term": "27 November 2010 – 27 November 2018"}]', 'wikipedia:person:Rauf_Aregbesola'),
('remi-sonaiya', 'Remi Sonaiya', 'Remi_Sonaiya', 'Oluremi Comfort Sonaiya is a Nigerian politician, educationalist and writer. She was Nigeria ''s only female presidential candidate in the 2015 general election under the platform of the KOWA Party. But recently lost her bid to Dr. Adesina Fagbenro Byron in representing the party again in 2019 election.', '1955-03-02', null, 'Ibadan, Oyo state, Nigeria', 'OY', 'female', 'KOWA', 'University of Ife; Cornell University', 'politician; writer; educationist', '[]', 'wikipedia:person:Remi_Sonaiya'),
('rochas-okorocha', 'Rochas Okorocha', 'Rochas_Okorocha', 'Owelle Rochas Anayo Okorocha is a Nigerian politician of Igbo extraction, from Imo State. He was the senator representing Imo West senatorial district at the 9th Nigerian Senate. From 2011 to 2019 he served as Governor of Imo State.', '1962-09-22', null, 'Ideato South, Imo State, Nigeria', 'IM', 'male', 'All Progressives Congress', 'Diploma in Public Administration', null, '[{"title": "Senator of the Federal Republic of Nigeria representing Imo State West District", "term": "June 2019 – June 2023"}, {"title": "5th Governor of Imo State", "term": "29 May 2011 – 29 May 2019"}]', 'wikipedia:person:Rochas_Okorocha'),
('rotimi-akeredolu', 'Rotimi Akeredolu', 'Rotimi_Akeredolu', 'Oluwarotimi Odunayo Akeredolu CON SAN was a Nigerian lawyer and politician who served as governor of Ondo State from 2017 until his death in 2023.', '1956-07-21', '2023-12-27', 'Owo, Western Region, British Nigeria (now in Ondo State, Nigeria)', 'ON', 'male', 'Action Congress of Nigeria', 'Obafemi Awolowo University', 'Lawyer; politician', '[{"title": "Governor of Ondo State", "term": "24 February 2017 – 27 December 2023"}, {"title": "President of the Nigerian Bar Association", "term": "2008 – August 2010"}, {"title": "Attorney General of Ondo State", "term": "1997–1999"}]', 'wikipedia:person:Rotimi_Akeredolu'),
('rotimi-amaechi', 'Rotimi Amaechi', 'Rotimi_Amaechi', 'Chibuike Rotimi Amaechi CON is a Nigerian politician, who served as the federal minister of transportation of Nigeria from 2015 to 2022 under the administration of President Muhammadu Buhari. He resigned to contest for Nigeria''s presidency under the governing All Progressive Congress (APC). He had previously served as governor of oil-rich Rivers State, from 2007 to 2015 and earlier, as speaker of the Rivers State House of Assembly from 1999 to 2007. On 9 April 2022, Amaechi declared interest to contest in the presidential election in 2023.', '1965-05-27', null, 'Ikwerre, Eastern Region (now in Rivers State), Nigeria', 'RI', 'male', 'African Democratic Congress', 'Bachelor of Arts (Honours) in English Literature; Bachelor of Laws (Honours)', 'Politician; lawyer', '[{"title": "Minister of Transportation", "term": "21 August 2019 – 16 May 2022"}, {"title": "Governor of Rivers State", "term": "25 October 2007 – 29 May 2015"}, {"title": "Speaker of the Rivers State House of Assembly", "term": "2 June 1999 – 4 June 2007"}]', 'wikipedia:person:Rotimi_Amaechi'),
('sadiq-wali', 'Sadiq Wali', 'Sadiq_Wali', 'Sadiq Aminu Wali is a Nigerian politician from Kano State, Nigeria. He served as the Kano State Commissioner for Water Resources and was involved in the People''s Democratic Party (PDP). He is the eldest son of former Minister of Foreign Affairs Aminu Wali.', '1974-03-11', null, 'Kano State', 'KN', 'male', 'People''s Democratic Party', null, 'Politician', '[]', 'wikipedia:person:Sadiq_Wali'),
('sadique-abubakar', 'Sadique Abubakar', 'Sadique_Abubakar', 'Sadique Baba Abubakar CFR psc (+) DFS GSS fwc fdc(+) MSc is a retired air marshal in the Nigerian Air Force and former Chief of the Air Staff of Nigeria.', '1960-04-08', null, 'Azare, Northern Region, Colonial Nigeria (now in Bauchi State, Nigeria)', 'BA', 'male', null, null, null, '[{"title": "Chief of the Air Staff", "term": "21 July 2015 – 29 January 2021"}]', 'wikipedia:person:Sadique_Abubakar'),
('saidu-samaila-sambawa', 'Saidu Samaila Sambawa', 'Saidu_Samaila_Sambawa', 'Saidu Samaila Sambawa is a Nigerian politician. As a member of the Peoples Democratic Party, he headed the Federal Ministry of Sports and Social Development until the June 2006 cabinet reshuffle, when he was replaced by Bala Bawa Ka''oje.', null, null, null, null, null, null, null, null, '[]', 'wikipedia:person:Saidu_Samaila_Sambawa'),
('salihu-sagir-takai', 'Salihu Sagir Takai', 'Salihu_Sagir_Takai', 'Salihu Sagir Takai is a Nigerian politician, an educationist, was a commissioner of Governor Malam Ibrahim Shekarau and the former chairman of Takai Local Government Area of Kano State and the 3 times Gubernatorial candidate of three parties ANPP (2011), PDP (2015), PRP (2019) and APC (2020).', '1955-12-20', null, 'Takai, Northern Region,', null, 'male', 'APC', null, 'Politician, Teacher', '[{"title": "Commissioner Kano State", "term": "Since 2003–2010"}, {"title": "Chairman", "term": "1999–2002"}]', 'wikipedia:person:Salihu_Sagir_Takai'),
('sam-egwu', 'Sam Egwu', 'Sam_Egwu', 'Sam Ominyi Egwu CON is a Nigerian politician and member of People''s Democratic Party (PDP) in Nigeria. He was elected Governor of Ebonyi State in the 1999 Ebonyi State gubernatorial election from 29 May 1999 to 29 May 2007. Dr Egwu is noted as pillar of educational development in Ebonyi state and Nigeria. He attended the University of Nigeria, Nsukka where he obtained a bachelor''s degree in Agriculture in 1981. He later received a master''s degrees in Agricultural from the University of Nigeria, Nsukka in 1987 and Doctorate in Agronomy from Enugu State University of Technology in 1996.', '1954-06-20', null, null, null, 'male', 'People''s Democratic Party', null, null, '[{"title": "Senator for the Ebonyi State North District", "term": "29 May 2015 – 14 June 2023"}, {"title": "Governor of Ebonyi State", "term": "29 May 1999 – 29 May 2007"}, {"title": "Minister of Education", "term": "17 December 2008 – 17 March 2010"}]', 'wikipedia:person:Sam_Egwu'),
('samuel-anyanwu', 'Samuel Anyanwu', 'Samuel_Anyanwu', 'Samuel Nnaemeka Anyanwu known as Sam Daddy is a Nigerian business executive, philanthropist and politician who served as the national secretary of the People’s Democratic Party (PDP) from November 2021 until his expulsion for anti-party activities in November 2025.', '1965-06-18', null, 'Amaimo, Ikeduru, Imo State, Nigeria', 'IM', 'male', 'PDP', 'University of Port Harcourt; Cambridge Judge Business School; Harvard Kennedy School', null, '[{"title": "National Secretary of the People''s Democratic Party (PDP)", "term": "November 2021 – November 2025"}, {"title": "Senator in the 8th Nigeria National Assembly", "term": "June 2015 – June 2019"}, {"title": "Member of the Imo State House of Assembly", "term": "2007–2015"}, {"title": "Chairman of Ikeduru Local Government Area", "term": "2004–2007"}, {"title": "Transition Committee Chairman, Ikeduru LGA", "term": "2003–2004"}]', 'wikipedia:person:Samuel_Anyanwu'),
('samuel-ortom', 'Samuel Ortom', 'Samuel_Ortom', 'Samuel Ioraer Ortom is a Nigerian politician, businessman, administrator and philanthropist. He was a Minister of State Trade and Investments and the Supervising Minister for Aviation in Nigeria during the presidency of Goodluck Jonathan in 2011. Ortom was elected governor of Benue State as a member of the All Progressives Congress in 2015, though he later defected to the People''s Democratic Party. He was re-elected as governor on 29 May 2019. Ortom''s tenure ended on 29 May 2023, succeeded by a Catholic priest of the opposition party, Rev. Fr. Hyacinth Iormem Alia.', '1961-04-23', null, 'Guma LGA, Benue State, Nigeria', 'BE', 'male', 'PDP', null, null, '[{"title": "18th Governor of Benue State", "term": "29 May 2015 – 29 May 2023"}, {"title": "Federal Minister of Industry, Trade and Investment Nigeria", "term": "11 July 2011 – 25 October 2014"}, {"title": "Supervising Minister, Nigerian Federal Ministry of Aviation Nigeria", "term": "14 February 2014 – 15 August 2014"}]', 'wikipedia:person:Samuel_Ortom'),
('sandy-ojang-onor', 'Sandy Ojang Onor', 'Sandy_Ojang_Onor', 'Sandy Ojang Onor is a Nigerian politician who served as the senator representing Cross River Central Senatorial District from 2019 to 2023. He was elected in 2019 to represent Cross River Central Senatorial District in the 9th Assembly of the Senate. He is a member of the Peoples Democratic Party (PDP). He was chosen as the Presidential candidate for the Peoples Democratic Party (PDP) for the upcoming 2027 Nigerian Presidential Election.', '1966-02-14', null, 'Ikom, Eastern Region (now in Cross River State), Nigeria', 'CR', 'male', 'Peoples Democratic Party', 'University of Calabar', null, '[{"title": "Senator for Cross River Central", "term": "11 June 2019 – 11 June 2023"}]', 'wikipedia:person:Sandy_Ojang_Onor'),
('sani-sha-aban', 'Sani Sha''aban', 'Sani_Sha''aban', 'Sani Mohammed Sha''aban is a Nigerian politician who served as a member of the House of Representatives representing Zaria Federal Constituency from 2003 to 2007.', null, null, null, null, 'male', null, null, null, '[]', 'wikipedia:person:Sani_Sha''aban'),
('seyi-makinde', 'Seyi Makinde', 'Seyi_Makinde', 'Oluseyi Abiodun Makinde is a Nigerian engineer, businessman, and politician who has served as the governor of Oyo State since 2019.', '1967-12-25', null, 'Ibadan, Western State (now in Oyo State), Nigeria', 'OY', 'male', 'Allied Peoples Movement', 'University of Lagos', 'Politician; engineer', '[{"title": "Governor of Oyo State", "term": "Since 29 May 2019"}]', 'wikipedia:person:Seyi_Makinde'),
('sha-aban-ibrahim-sharada', 'Sha''aban Ibrahim Sharada', 'Sha''aban_Ibrahim_Sharada', 'Sha''aban Ibrahim Sharada is a Nigerian politician and Journalist from Kano state who was the Personal Assistant to President Muhammad Buhar i before he become a Member of the House of Representatives in 2019.', '1982-01-01', null, 'Kano', 'KN', 'male', 'ADP', 'Bayero University, Kano', 'Politics', '[{"title": "Member House of Representative", "term": "Since 10 June 2019"}, {"title": "Personal Assistant To the President Federal Republic of Nigeria Muhammad Buhari", "term": "30 February 2016 – 10 June 2019"}]', 'wikipedia:person:Sha''aban_Ibrahim_Sharada'),
('siminalayi-fubara', 'Siminalayi Fubara', 'Siminalayi_Fubara', 'Amaopusenibo Siminalayi Fubara is a Nigerian politician and accountant who has served as the governor of Rivers State since 23 May 2023. A member of the All Progressives Congress since December 2025, Fubara was suspended as governor on 18 March 2025 following an emergency rule by President Bola Tinubu. On 18 September 2025, he was re-instated.', '1975-01-28', null, 'Opobo, Rivers State, Nigeria', 'RI', 'male', 'All Progressives Congress', 'Rivers State University; University of Port Harcourt', null, '[{"title": "Governor of Rivers State", "term": "Since 18 September 2025"}]', 'wikipedia:person:Siminalayi_Fubara'),
('simon-lalong', 'Simon Lalong', 'Simon_Lalong', 'Simon Bako Lalong CON is a Nigerian lawyer and politician who has served as the senator representing the Plateau South senatorial district since 2023. He previously served as the minister of labour and employment in 2023, and as the governor of Plateau State from 2015 to 2023.', '1963-05-05', null, 'Shendam, Northern Region (now in Plateau State), Nigeria', 'PL', 'male', 'All Progressives Congress', 'Ahmadu Bello University; University of Jos', 'Politician; lawyer; businessman', '[{"title": "Senator for Plateau South", "term": "Since 20 December 2023"}, {"title": "Minister of Labour and Employment", "term": "21 August 2023 – 20 December 2023"}, {"title": "Governor of Plateau State", "term": "29 May 2015 – 29 May 2023"}, {"title": "Speaker of the Plateau State House of Assembly", "term": "2000–2007"}]', 'wikipedia:person:Simon_Lalong'),
('sonni-ogbuoji', 'Sonni Ogbuoji', 'Sonni_Ogbuoji', 'Sonni Ogbuoji is a Nigerian politician who was elected Senator for Ebonyi South, in Ebonyi State, Nigeria in the 9 April 2011 national elections. He was elected on the People''s Democratic Party (PDP) ticket. He left the senate in the 2019. Sonni hails from Ebunwana Edda in Afikpo South local government area of Ebonyi state.', null, null, null, null, 'male', 'All Progressives Party', null, null, '[{"title": "Senator for Ebonyi South", "term": "May 2011 – May 2019"}]', 'wikipedia:person:Sonni_Ogbuoji'),
('sule-lamido', 'Sule Lamido', 'Sule_Lamido', 'Sule Lamido is a Nigerian politician who served as the governor of Jigawa State from 2007 to 2015. He previously served as the foreign affairs minister of Nigeria from 1999 to 2003. He is a member of the Peoples Democratic Party (PDP).', '1948-08-30', null, 'Bamaina, Northern Region, British Nigeria (now in Jigawa State, Nigeria)', 'JI', 'male', 'Peoples Democratic Party', null, 'Politician', '[{"title": "Governor of Jigawa State", "term": "29 May 2007 – 29 May 2015"}, {"title": "Minister of Foreign Affairs", "term": "1999–2003"}, {"title": "Member of the House of Representatives of Nigeria from Kano State", "term": "1979–1983"}]', 'wikipedia:person:Sule_Lamido'),
('suleiman-othman-hunkuyi', 'Suleiman Othman Hunkuyi', 'Suleiman_Othman_Hunkuyi', 'Suleiman Othman Hunkuyi is a Nigerian politician who became the senator of Kaduna North Senatorial District at the Federal Republic of Nigeria''s Senate in 2015 Nigerian general elections.', '1959-07-17', null, 'Kudan LGA, Kaduna State, Nigeria', 'KD', 'male', 'People''s Democratic Party - PDP', 'Ahmadu Bello University', 'Teacher; politician', '[{"title": "Senator for Kaduna North", "term": "June 2015 – June 2019"}]', 'wikipedia:person:Suleiman_Othman_Hunkuyi'),
('sullivan-chime', 'Sullivan Chime', 'Sullivan_Chime', 'Sullivan Iheanacho Chime was elected governor of Enugu State in Nigeria in April 2007, taking office on 29 May 2007. He is a member of the People''s Democratic Party (PDP). He was reelected on 26 April 2011.', '1959-04-10', null, 'Udi, Udi LGA, Enugu State, Nigeria', 'EN', 'male', 'APC', null, null, '[{"title": "4th Governor of Enugu State", "term": "29 May 2007 – 29 May 2015"}, {"title": "1st Attorney General of Enugu State", "term": "2001 – May 2007"}]', 'wikipedia:person:Sullivan_Chime'),
('sunday-onuoha', 'Sunday Onuoha', 'Sunday_Onuoha', 'Sunday Ndukwo Onuoha is the founder and president of Vision Africa International and the co-chair, Interfaith Dialogue Forum for Peace. In 2003, he was consecrated bishop in the Nigerian methodist church, and appointed special assistant on privatization in Olusegun Obasanjo ''s cabinet.', '1964-03-22', null, 'Item, Abia State, Nigeria', 'AB', 'male', null, null, 'Bishop, author, educationist, minister', '[]', 'wikipedia:person:Sunday_Onuoha'),
('tanko-yakasai', 'Tanko Yakasai', 'Tanko_Yakasai', 'Alhaji Salihu Abubakar Tanko Yakasai OFR is a Nigerian politician and elder statesman. A self-described Marxist-Leninist and a founding member of the Northern Elements Progressive Union, he was a prominent figure in Nigeria''s radical political circles in the 1950s and 1960s. He later held various public offices, including State Commissioner in Kano under Military Governor Audu Bako and Special Assistant on National Assembly Liaison to President Shehu Shagari during the Second Republic. He is a founding member of Arewa Consultative Forum.', '1925-12-05', null, 'Kofar Mata quarters, Kano, Colonial Nigeria', 'KN', 'male', 'People''s Salvation Party', null, null, '[{"title": "Special Assistant to the President of Nigeria on National Assembly Liaison", "term": "1979–1983"}, {"title": "Kano State Commissioner for Finance", "term": "1971–1975"}, {"title": "Kano State Commissioner for Forestry, Community Development and Cooperatives", "term": "1971–1972"}, {"title": "Kano State Commissioner for Information", "term": "1967–1971"}]', 'wikipedia:person:Tanko_Yakasai'),
('terhemen-tarzoor', 'Terhemen Tarzoor', 'Terhemen_Tarzoor', 'Terhemen Tarzoor is a Nigerian Economist and Real Estate Developer from Makurdi Local Government Area of Benue State in North Central Nigeria who currently serves as Nigerian Ambassador to Namibia. He previously served as Speaker in the Benue State House of Assembly in which he represented his constituency. Tarzoor came to prominence when he ran unsuccessfully for the seat of the Governor of Benue State, losing to Samuel Ortom in the 2015 General Elections. He finished runner-up despite running as a favorite candidate on the platform of the then ruling People''s Democratic Party (PDP).', '1972-01-26', null, 'Makurdi, Nigeria', null, 'male', null, 'Mount St Gabriel Secondary School Makurdi', 'Economist, Real Estate Developer, Businessman', '[]', 'wikipedia:person:Terhemen_Tarzoor'),
('teslim-folarin', 'Teslim Folarin', 'Teslim_Folarin', 'Teslim Kolawole Folarin OFR is a Nigerian politician, he was the gubernatorial candidate of the All Progressives Congress in Oyo State for the 2023 gubernatorial election which he lost to the incumbent governor Seyi Makinde. He previously served as the senator representing Oyo Central senatorial district from 2003 to 2011; and from 2019 to 2023.', '1963-10-30', null, 'Ibadan, Western Region (now in Oyo State), Nigeria', 'OY', 'male', 'All Progressive Congress', 'Methodist Boys'' High School, Lagos', 'Politician', '[{"title": "Senator for Oyo Central", "term": "11 June 2019 – 11 June 2023"}]', 'wikipedia:person:Teslim_Folarin'),
('theodore-orji', 'Theodore Orji', 'Theodore_Orji', 'Theodore Ahamefule Orji CON is a Nigerian politician who served as the senator representing Abia Central senatorial district from 2015 to 2023. He previously served as the governor of Abia State from 2007 to 2015. He was a career civil servant, and served as chief of staff to the Abia State governor, Orji Uzor Kalu.', '1950-11-09', null, 'Umuahia, Southern Region, British Nigeria (now in Abia State, Nigeria)', 'AB', 'male', 'Peoples Democratic Party', null, 'Politician', '[{"title": "Senator for Abia Central", "term": "9 June 2015 – 11 June 2023"}, {"title": "8th Governor of Abia State", "term": "29 May 2007 – 29 May 2015"}]', 'wikipedia:person:Theodore_Orji'),
('timipre-sylva', 'Timipre Sylva', 'Timipre_Sylva', 'Timipre Marlin Sylva CON is a Nigerian politician who served as the minister of state for Petroleum Resources of Nigeria from 2019 to 2023. He previously served as governor of Bayelsa State from 2007 to 2012.', '1964-07-07', null, 'Okpoama-Brass, Eastern Region (now in Bayelsa State), Nigeria', 'BY', 'male', 'All Progressives Congress', 'University of Port Harcourt; UBIS University', 'Politician', '[{"title": "Minister of State for Petroleum Resources", "term": "21 August 2019 – 31 March 2023"}, {"title": "7th & 9th Governor of Bayelsa State", "term": "27 May 2008 – 27 January 2012"}, {"title": "Special Assistant to Minister of State for Petroleum Resources", "term": "2004–2007"}]', 'wikipedia:person:Timipre_Sylva'),
('titus-uba', 'Titus Uba', 'Titus_Uba', 'Titus Uba is a Nigerian politician who is currently serving as speaker of the Benue State House of Assembly since August 2018. Uba represents Kyan constituency in the state assembly. His emergence as the speaker of the house followed a vote of no confidence and the subsequent impeachment of the former speaker of the assembly, Terkimbi Ikyange. In 2019, Uba was re-elected speaker for the 9th Benue State House of Assembly.', '1965-09-25', null, null, null, 'male', 'People''s Democratic Party, PDP', null, null, '[]', 'wikipedia:person:Titus_Uba'),
('tokunbo-afikuyomi', 'Tokunbo Afikuyomi', 'Tokunbo_Afikuyomi', 'Tokunbo Afikuyomi is a Nigerian politician who was elected Senator for the Lagos Central constituency at the start of the Nigerian Fourth Republic, running on the Alliance for Democracy (AD) platform. He took office in June 1999. He changed constituency in April 2002 and ran on the AD platform for the Lagos West constituency instead, after senator Wahab Dosunmu defected to the PDP.', null, null, 'Lagos State, Nigeria', 'LA', 'male', null, null, null, '[{"title": "Senator for Lagos West", "term": "3 June 2003 – 5 June 2007"}, {"title": "Senator for Lagos Central", "term": "3 June 1999 – 3 June 2003"}]', 'wikipedia:person:Tokunbo_Afikuyomi'),
('tony-nwoye', 'Tony Nwoye', 'Tony_Nwoye', 'Dr. Tony Okechukwu Nwoye is a Nigerian politician, serving as the Senator of Anambra North Senatorial District. He was a former member of the Nigerian House of Representatives representing the people of Anambra East/West constituency of Anambra state. He was a gubernatorial candidate of the People''s Democratic Party, PDP, in the 2013 Anambra State governorship election and was also a gubernatorial candidate of the APC in the 2017 Anambra State governorship election. He is currently a member of the Labour Party and is a Senator under the Party in the 10th Nigerian Senate.', '1974-09-13', null, 'Onitsha, Anambra State, Nigeria', 'AN', 'male', 'Labour Party', null, null, '[{"title": "Senator for Anambra North", "term": "Since June 2023"}]', 'wikipedia:person:Tony_Nwoye'),
('tonye-cole', 'Tonye Cole', 'Tonye_Cole', 'Tonye Patrick Cole is a Nigerian billionaire businessman, he is the co-founder and former Group Executive Director of Sahara Group an energy conglomerate with operations spanning the entire energy chain in Nigeria and neighbouring West African countries to East Africa and beyond. The Group operates in 38 countries around the world with over 4,000 employees and annual turnover of $11 billion.', '1967-01-11', null, 'Abonnema, Eastern Region, Nigeria (now in Rivers State, Nigeria)', 'RI', 'male', 'All Progressives Congress', 'Harvard Business School; University of Brasília; University of Lagos', 'Co-Founder, Sahara Group', '[]', 'wikipedia:person:Tonye_Cole'),
('tonye-princewill', 'Tonye Princewill', 'Tonye_Princewill', 'Tonye Princewill is a Nigerian investor, politician, film producer and philanthropist Currently the Paramount ruler of Da Ogo / Queen Elebabene Royal Group of Houses. He was the 2015 and 2007 candidate. for Governor of Rivers State. He was a member of the All Progressives Congress (APC) and the son of King T.J.T. Princewill of the Kalabari Kingdom of Rivers State, Nigeria. He resigned from All Progressives Congress APC because of same faith presidential ticket by the party.', '1969-01-04', null, 'Kalabari Kingdom Rivers State, Nigeria)', null, 'male', null, 'Shire Oak, Leeds, United Kingdom St Gemmas, Leeds, United Kingdom; Hillcrest School (Jos, Nigeria); Federal Government College, Port Harcourt', 'Paramount Ruler Nigerian Investor, Politician, Film Producer, Philanthropist', '[]', 'wikipedia:person:Tonye_Princewill'),
('tunji-olurin', 'Tunji Olurin', 'Tunji_Olurin', 'Adetunji Idowu Ishola Olurin mni was a Nigerian general who served as the military Governor of Oyo State from 1985 to 1988 and Field Commander of ECOMOG Peacekeeping Force in Liberia from 1992 to 1993 during the First Liberian Civil War. Olurin retired from service in 1993, and was a member of Peoples Democratic Party (PDP). He was administrator of Ekiti State from 19 October 2006 until 27 April 2007.', '1944-12-03', '2021-08-20', 'Ilaro, Southern Region, British Nigeria (now in Ogun State, Nigeria)', 'OG', 'male', 'Peoples Democratic Party', null, 'Politician; military officer', '[{"title": "Administrator of Ekiti State", "term": "19 October 2006 – 27 April 2007"}, {"title": "Commander, ECOMOG Peacekeeping Force, Liberia", "term": "December 1992 – October 1993"}, {"title": "Military Governor of Oyo State", "term": "September 1985 – July 1988"}]', 'wikipedia:person:Tunji_Olurin'),
('uba-sani', 'Uba Sani', 'Uba_Sani', 'Uba Sani is a Nigerian engineer and politician who has served as Governor of Kaduna State since 2023. He previously served as the Senator representing Kaduna central senatorial district from 2019 to 2023.', '1970-12-31', null, 'Zaria, North-Central State (now Kaduna State), Nigeria', null, 'male', 'All Progressives Congress', 'Kaduna Polytechnic; University of Abuja; University of Calabar', 'Politician; engineer', '[{"title": "Governor of Kaduna State", "term": "Since 29 May 2023"}, {"title": "Senator for Kaduna Central", "term": "11 June 2019 – 29 May 2023"}]', 'wikipedia:person:Uba_Sani'),
('uche-ekwunife', 'Uche Ekwunife', 'Uche_Ekwunife', 'Uche Lilian Ekwunife is a banker and a Nigerian politician who was recently a senator representing the people of Anambra Central Senatorial District of Anambra State. She is known as one of the most active female senators in the House.', '1970-12-12', null, 'Igbo-Ukwu, Anambra, Nigeria', 'AN', 'female', 'People''s Democratic Party', 'University of Calabar (BSc); Nnamdi Azikiwe University (MBA)', null, '[{"title": "DG. Southeast Governors'' Forum, Senator of the Federal Republic of Nigeria from Anambra Central Senatorial District", "term": "Since June 2015"}, {"title": "Member of the Nigerian House of Representatives from Anambra", "term": "June 2007 – June 2015"}]', 'wikipedia:person:Uche_Ekwunife'),
('uche-nwosu', 'Uche Nwosu', 'Uche_Nwosu', 'Uche Nwosu (pronunciation), is a Nigerian politician and former Deputy Chief of Staff to the Imo State Government from 2011 to 2013, Commissioner for Lands from 2013 to 2015 and was the Chief of Staff from 2015 to 2019.', '1975-08-08', null, null, null, 'male', null, 'Imo State University', 'Politician', '[]', 'wikipedia:person:Uche_Nwosu'),
('uche-ogah', 'Uche Ogah', 'Uche_Ogah', 'Uchechukwu Sampson Ogah is a Nigerian business magnate, investor and philanthropist who served as Minister of State for Mines and Steel Development during the presidency of Muhammadu Buhari. He is the founder of Master Energy Group, a conglomerate with over 15 subsidiaries and interests across a variety of industries. Ogah holds the Nigerian national honours, the Officer of the Order of the Niger (OON) and the Commander of the Order of Niger (CON).', '1969-12-22', null, 'Abia State', 'AB', 'male', null, 'University of Nigeria Nsukka, University of Lagos, Institute of Management Technology Enugu, Ogun State University', 'Politician, Businessman, President (Master Energy Group)', '[]', 'wikipedia:person:Uche_Ogah'),
('udom-gabriel-emmanuel', 'Udom Gabriel Emmanuel', 'Udom_Gabriel_Emmanuel', 'Udom Gabriel Emmanuel // is a Nigerian politician and accountant who served as governor of Akwa Ibom State from 2015 to 2023. He contested for the office of governor in the April 2015 elections on the platform of Peoples Democratic Party.', '1966-07-11', null, 'Awa Iman, Onna, Eastern Region, Nigeria (now in Akwa Ibom State)', 'AK', 'male', 'Peoples Democratic Party', 'University of Lagos; London Business School; INSEAD, France', null, '[{"title": "Governor of Akwa Ibom State", "term": "29 May 2015 – 29 May 2023"}]', 'wikipedia:person:Udom_Gabriel_Emmanuel'),
('umar-namadi', 'Umar Namadi', 'Umar_Namadi', 'Umar Namadi is a Nigerian accountant and politician who has served as the governor of Jigawa State since 2023. He was the deputy governor of Jigawa State from May 2019 to May 2023.', '1963-04-07', null, 'Kafin Hausa, Northern Region, Nigeria (now in Jigawa State)', 'JI', 'male', 'All Progressive Congress', 'Bayero University Kano', 'Politician; accountant', '[{"title": "Governor of Jigawa State", "term": "Since 29 May 2023"}, {"title": "Deputy Governor of Jigawa State", "term": "29 May 2019 – 29 May 2023"}]', 'wikipedia:person:Umar_Namadi'),
('umaru-musa-yar-adua', 'Umaru Musa Yar''Adua', 'Umaru_Musa_Yar''Adua', 'Umaru Musa Yar''Adua GCFR was a Nigerian politician who served as the president of Nigeria from 2007 until his death in May 2010. He won the Nigerian presidential election held on 21 April 2007, and was sworn in on 29 May 2007.', '1951-08-16', '2010-05-05', 'Katsina, Northern Region, British Nigeria (now in Katsina State, Nigeria)', 'KT', 'male', 'Peoples Democratic Party', 'Barewa College; Ahmadu Bello University', 'Politician, teacher, businessman', '[{"title": "13th President of Nigeria", "term": "29 May 2007 – 5 May 2010"}, {"title": "Governor of Katsina", "term": "29 May 1999 – 29 May 2007"}]', 'wikipedia:person:Umaru_Musa_Yar''Adua'),
('umaru-tanko-al-makura', 'Umaru Tanko Al-Makura', 'Umaru_Tanko_Al-Makura', 'Umaru Tanko Al-Makura is a Nigerian businessman and politician and also a former governor and senator in Nasarawa State in the All Progressive Congress (APC).', null, null, 'Lafia, Nasarawa State, Nigeria', 'NA', 'male', 'All Progressives Congress', 'Dunama Primary School', 'Businessperson, Politician', '[{"title": "Fmr Senator for Nasarawa State South district", "term": "Since June 11, 2019"}, {"title": "Governor of Nasarawa State", "term": "29 May 2011 – 29 May 2019"}]', 'wikipedia:person:Umaru_Tanko_Al-Makura'),
('umo-eno', 'Umo Eno', 'Umo_Eno', 'Umo Bassey Eno is a Nigerian clergyman and politician who is the Governor of Akwa Ibom State, Nigeria. He was the former Commissioner for Lands and Water Resources in Akwa Ibom State, and the founder of All Nations Christian Ministry International.', '1964-04-24', null, 'Nsit-Ubium, Eastern Region, Nigeria (now in Akwa Ibom State)', 'AK', 'male', 'All Progressives Congress', 'University of Uyo', 'Politician; businessman', '[{"title": "Governor of Akwa Ibom State", "term": "Since 29 May 2023"}, {"title": "Akwa Ibom State Commissioner for Lands and Water Resources", "term": "2021–2022"}]', 'wikipedia:person:Umo_Eno'),
('usani-uguru-usani', 'Usani Uguru Usani', 'Usani_Uguru_Usani', 'Usani Uguru Usani is a Nigerian pastor, lecturer and politician who served as Minister of Niger Delta Affairs in the Nigerian government.', '1961-01-27', null, 'Nko, Yakurr, Yakurr, Cross River State, Nigeria', 'CR', 'male', 'All Progressives Congress', 'University of Jos', null, '[{"title": "Minister of Niger Delta", "term": "11 November 2015 – 29 May 2019"}, {"title": "Commissioner for Youth, Sports & Social Development and Commissioner of Information, Cross River State", "term": "July 1995 – February 1997"}, {"title": "Commissioner for Agriculture, Water Resources and Rural Development, Cross River State", "term": "February 1997 – May 1999"}]', 'wikipedia:person:Usani_Uguru_Usani'),
('usman-albishir', 'Usman Albishir', 'Usman_Albishir', 'Shehu Usman Albishir was a Nigerian senator representing Yobe North constituency of Yobe State. He was a member of the business family of Alhaji Albishir Abdullahi and Late Hajiya Fatima Albishir.', '1945-06-15', '2012-07-02', 'Nguru, Yobe State, Nigeria', 'YO', 'male', 'People''s Democratic Party', null, null, '[{"title": "Senator of the Federal Republic of Nigeria from Yobe State North District", "term": "29 May 1999 – 5 June 2007"}]', 'wikipedia:person:Usman_Albishir'),
('usman-bayero-nafada', 'Usman Bayero Nafada', 'Usman_Bayero_Nafada', 'Senator Usman Bayero Nafada is a former Deputy Speaker of the House of Representatives of Nigeria representing Dukku/Nafada Federal Constituency of Gombe state, and a former senator for the Gombe North senatorial district in 2015 under the umbrella of the People''s Democratic Party (PDP). He was the 2019 Peoples Democratic Party''s gubernatorial candidate in Gombe State. Nafada holds different titles and awards which include Sarkin Yakin Nafada, Dan Rimin Gona, Madawakin Akko, Durbin Tangale, Maje Keran Funakaye, Enyi of Igbo Anambara, Garkuwan Matasan Arewa, and Commander of the Order of Niger (CON).', '1961-01-02', null, null, null, 'male', 'People''s Democratic Party', null, 'Politician', '[{"title": "Senator for Gombe North", "term": "9 June 2015 – 9 June 2019"}, {"title": "Deputy Speaker of the House of Representatives of Nigeria", "term": "2 November 2007 – 6 June 2011"}]', 'wikipedia:person:Usman_Bayero_Nafada'),
('usman-sa-idu-nasamu-dakingari', 'Usman Sa''idu Nasamu Dakingari', 'Usman_Sa''idu_Nasamu_Dakingari', 'Usman Sa''idu Nasamu Dakingari is a Nigerian politician who served as governor of Kebbi State from 2007 to 2015. He was elected governor in April 2007, taking office on 29 May 2007. He is a member of the People''s Democratic Party (PDP). He was reelected on 26 April 2011. However, on 24 February 2012, the Supreme Court upheld a ruling by the Kebbi State Governorship Election Petition Tribunal that nullified his election, and ordered a fresh election within 90 days. He was elected again on 31 March 2012 and took office on 2 April.', '1959-09-13', null, 'Dakin Gari, Kebbi State, Nigeria', 'KE', 'male', 'People''s Democratic Party', null, null, '[{"title": "Governor of Kebbi State", "term": "2 April 2012 – 29 May 2015"}]', 'wikipedia:person:Usman_Sa''idu_Nasamu_Dakingari'),
('valentine-ozigbo', 'Valentine Ozigbo', 'Valentine_Ozigbo', 'Valentine Chineto \"Val\" Ozigbo is a Nigerian politician and business executive. He is the immediate past President and Chief Executive Officer of Transnational Corporation of Nigeria plc (Transcorp), a diversified conglomerate with strategic investments and core interests in the hospitality, agribusiness and energy sectors He was appointed to the position in 2019.', null, null, null, null, 'male', 'All Progressives Congress', null, null, '[{"title": "President of Transcorp Plc Nigeria", "term": "2018–2020"}]', 'wikipedia:person:Valentine_Ozigbo'),
('victor-attah', 'Victor Attah', 'Victor_Attah', 'Obong Victor Bassey Attah is a Nigerian politician who served as the Governor of Akwa Ibom State from 29 May 1999 to 29 May 2007. He was a member of the Board of Trustees of the Peoples Democratic Party (PDP).', '1938-11-20', null, 'Okop Ndua Erong, Asutan Ekpe, Ibesikpo Asutan LGA, Akwa Ibom State, Nigeria', 'AK', 'male', null, null, null, '[{"title": "2nd Governor of Akwa Ibom State", "term": "29 May 1999 – 29 May 2007"}]', 'wikipedia:person:Victor_Attah'),
('virginia-etiaba', 'Virginia Etiaba', 'Virginia_Etiaba', 'Dame Virginia Ngozi Etiaba CON is a Nigerian politician who served as Deputy Governor of Anambra State, a state in South-Eastern Nigeria, from March 2006 to November 2006 under Peter Obi tenure. She later became the Governor of Anambra State between November 2006 to February 2007. Etiaba is the first woman to serve as governor of a Nigerian state.', '1942-11-11', null, 'Nnewi, Anambra', 'AN', 'female', null, null, null, '[{"title": "Governor of Anambra State", "term": "2 November 2006 – 9 February 2007"}, {"title": "Deputy Governor of Anambra State", "term": "17 March 2006 – 2 November 2006"}]', 'wikipedia:person:Virginia_Etiaba'),
('willie-obiano', 'Willie Obiano', 'Willie_Obiano', 'Willie Mmadụabụrochukwu Obiano CFR is a Nigerian politician and banker who served as the fourth Governor of Anambra State from 17 March 2014 to 17 March 2022', '1955-08-08', null, 'Aguleri, Anambra State, Nigeria', 'AN', 'male', 'All Progressives Grand Alliance', null, 'Politician; banker', '[{"title": "4th Governor of Anambra State", "term": "17 March 2014 – 17 March 2022"}]', 'wikipedia:person:Willie_Obiano'),
('yahaya-abdulkarim', 'Yahaya Abdulkarim', 'Yahaya_Abdulkarim', 'Malam Yahaya Abdulkarim is a Nigerian politician who was governor of Sokoto State, between January 1992 and November 1993, during General Ibrahim Babangida ''s attempted transition to democracy. After the return to democracy in 1999, he became a power in the Zamfara State branch of the People''s Democratic Party (PDP), and served for a while in the cabinet of president Olusegun Obasanjo.', '1944-08-21', null, 'Talata Mafara, Northern Region, British Nigeria (now in Zamfara State, Nigeria)', 'ZA', 'male', 'People''s Democratic Party', null, null, '[{"title": "Governor of Sokoto State", "term": "January 1992 – November 1993"}]', 'wikipedia:person:Yahaya_Abdulkarim'),
('yahaya-bello', 'Yahaya Bello', 'Yahaya_Bello', 'Yahaya Adoza Bello CON is a Nigerian businessman, politician. He served as the governor of Kogi State from 2016 to 2024. A member of the All Progressives Congress, Bello was the youngest governor in Nigeria throughout his term in office.', '1975-06-18', null, 'Okene, Kwara State (now in Kogi State), Nigeria', 'KO', 'male', 'All Progressives Congress', 'MBA', 'Politician; accountant; businessman', '[{"title": "Governor of Kogi State", "term": "27 January 2016 – 27 January 2024"}]', 'wikipedia:person:Yahaya_Bello'),
('yusuf-sulaimon-lasun', 'Yusuf Sulaimon Lasun', 'Yusuf_Sulaimon_Lasun', 'Yusuf Sulaimon Lasun is a Nigerian politician who served as the deputy speaker of the House of Representatives of Nigeria from 2015 to 2019. He represented Irepodun / Olurunda / Osogbo /Orolu Federal Constituency of Osun State in the House.', '1960-10-04', null, 'Ilobu, Western Region, Nigeria (now in Osun State)', 'OS', 'male', 'Peoples Democratic Party', 'University of Ibadan; Obafemi Awolowo University', 'Politician; engineer', '[{"title": "Deputy Speaker of the House of Representatives of Nigeria", "term": "9 June 2015 – 9 June 2019"}, {"title": "Member of the House of Representatives of Nigeria from Osun", "term": "6 June 2011 – 9 June 2019"}]', 'wikipedia:person:Yusuf_Sulaimon_Lasun'),
('yusuf-tuggar', 'Yusuf Tuggar', 'Yusuf_Tuggar', 'Yusuf Maitama Tuggar OON is a Nigerian diplomat and politician who was a former Nigerian minister of foreign affairs from 21 August 2023 to 30 March 2026. He served as the Nigerian Ambassador to Germany from 2017 to 2023. He was previously a member of the Nigerian House of Representatives from 2007 to 2011 representing Gamawa; and he ran twice for the office of the governor of Bauchi State.', '1967-03-12', null, 'North-Eastern State, Nigeria', null, 'male', 'All Progressives Congress', 'United States International University; University of Bath; University of Cambridge', 'Politician; diplomat', '[{"title": "Minister of Foreign Affairs", "term": "21 August 2023 – 30 March 2026"}, {"title": "Nigerian Ambassador to Germany", "term": "September 2017 – 21 August 2023"}, {"title": "Member of the House of Representatives of Nigeria from Bauchi", "term": "5 June 2007 – 6 June 2011"}]', 'wikipedia:person:Yusuf_Tuggar');
